INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,tags) VALUES
('F-001','identity',NULL,'Central project identity','The central project is DiceBox Campaign Helper: a semantic campaign compiler, runtime, and Foundry VTT bridge with an associated Foundry module.','global','canonical','locked','SRC-COMPILE','project-name,scope'),
('F-002','identity',NULL,'Semantic identity','Stable DiceBox Campaign Helper IDs are canonical identity; Foundry _id, UUID, names, paths, and file names are runtime bindings only.','global','canonical','locked','SRC-FOUNDATION','identity,uuid'),
('F-003','architecture',NULL,'Projection boundary','Campaign Assistant/DiceBox semantic specifications are authoritative; Foundry documents, images, Regions, Activities, and module state are compiled projections or runtime bindings.','global','canonical','locked','SRC-FOUNDATION','semantic,projection'),
('F-004','safety',NULL,'Mutation pipeline','AI intent must pass trust classification, live reconnaissance, capability resolution, schema/reference/authority checks, sovereignty checks, dry run, transaction, read-back, postcondition verification, and receipt/recovery.','global','canonical','locked','SRC-FOUNDATION','safety,transaction'),
('F-005','authority',NULL,'No direct player protected writes','Player-triggered protected mutations route to an active authorized GM/executor; privilege elevation transfers execution, not permission.','global','canonical','locked','SRC-REGION-DOSSIER','permissions,gm-relay'),
('F-006','runtime',NULL,'Runtime sovereignty','During play, runtime state is sovereign. Rebuilds preserve HP, resources, positions, effects, combat chronology, player/GM changes, foreign content, and moved/destroyed furnishing unless an explicit reviewed repair is requested.','global','canonical','locked','SRC-FOUNDATION','live-sync,sovereignty'),
('F-007','mechanics',NULL,'Native first','Use native Foundry/D&D5e primitives when semantically complete and exact-stack eligible; optional modules and macros are capability-gated adapters.','global','canonical','locked','SRC-FOUNDATION','native-first,capability'),
('F-008','mechanics',NULL,'One mechanical owner','Exactly one subsystem owns each mechanic; presentation systems never become mechanical authority.','global','canonical','locked','SRC-FOUNDATION','ownership'),
('F-009','mechanics',NULL,'Utility versus Use','DiceBox preserves Utility and Use as separate semantic categories even if D&D5e 5.3.3 exposes only the utility runtime type.','global','canonical','locked','SRC-COMPILE','activities,utility,use'),
('F-010','activities',NULL,'Activity-first compiler','For D&D5e mechanics, prefer native Activity, then Midi resolution/composition, then Effects/DAE, Region/Scene, and only then an Additional Activity or macro for an uncovered verb.','global','canonical','locked','SRC-COMPILE','activities,midi'),
('F-011','activities',NULL,'Midi role','Midi-QOL owns resolution workflow such as targeting, attack/save/damage adjudication, reactions, effects, OverTime, cleanup, and undo where supported; Activities express the action.','global','static','active','SRC-CHAT-AITRAP','midi,workflow'),
('F-012','effects',NULL,'DAE role','DAE is an optional extension to native Active Effects; DAE lifecycle callbacks are effect-state behavior, while Midi macros are transient Activity workflow behavior.','global','static','active','SRC-CHAT-MACRO','dae,effects'),
('F-013','regions',12,'Region authority','Scene Regions contain geometry, embedded Behaviors, and event subscriptions; Regionwright/DMF provide explicit selection, owned reconciliation, reset, and capability gating.','project','static','active','SRC-REGION-DOSSIER','regions,behaviors'),
('F-014','spatial',37,'Spatial Blueprint','Physical geometry, topology, clearance, anchors, and relationships exist before pixels; image output and Foundry placeables are projections from the same blueprint.','global','canonical','locked','SRC-FOUNDATION','spatial,maps'),
('F-015','images',39,'Images are renderers','Generated images cannot define topology, scale, exact text, puzzle logic, furnishing mechanics, or Foundry rules. Approved bytes are reused by hash during normal rebuilds.','global','canonical','locked','SRC-FOUNDATION','images,provenance'),
('F-016','database',NULL,'Knowledge base layering','The KB is layered into canonical contracts, project dossiers, campaign packs, historical conversations, evidence, trials, and implementation contracts.','global','canonical','locked','SRC-AUDIT','kb,provenance'),
('F-017','versions',NULL,'Target stack','DiceBox creation targets Foundry 14.367 Stable 9 and D&D5e 5.3.3; Midi, DAE, SocketLib, and other modules are optional exact-stack capabilities.','global','canonical','locked','SRC-FOUNDATION','versions'),
('F-018','evidence',40,'Readiness evidence','Successful import, static tests, or a successful chat response is not Ready-to-Play; certification needs exact environment, actual document use, player-role, recovery, and blocker evidence.','global','canonical','locked','SRC-FOUNDATION','certification'),
('F-019','regionwright',12,'Regionwright current evidence','Regionwright passes 114 deterministic tests, but live module discovery, canvas selection, real native behavior write/reset, event context, and fresh two-client proof remain required.','project','deterministic','active','SRC-REGION-VERIFY','regionwright,evidence'),
('F-020','dmf',13,'DMF current evidence','Dungeon Master''s Forge verification passes with zero failures/warnings and reports 274 AI-service plus 168 module tests, but static/isolated evidence does not establish full in-world functionality.','project','deterministic','active','SRC-DMF-VERIFY','dmf,evidence'),
('F-021','release',NULL,'Source hygiene','Region Editor is largely untracked and DMF is a dirty tester workspace; neither should be cleaned, reset, or treated as an immutable release source without explicit snapshotting.','project','static','active','SRC-AUDIT','release,provenance'),
('F-022','campaign',NULL,'Campaign scope boundary','Iggwilv Tower, Prime Arachnid, puzzle names, authored UUIDs, and exact campaign topology remain campaign/project packs, not global DiceBox rules.','campaign','static','active','SRC-REGION-DOSSIER','campaign-scope'),
('F-023','research',NULL,'Numbered research status','The linked Campaign Assistant project records Research #1-#40 complete/closed, while targeted deepening and implementation/certification studies remain separately tracked.','project','static','active','SRC-CHAT-RESEARCH','research-status'),
('F-024','research',NULL,'Research self-update rule','Every research pass or sub-pass must update the research master, machine-readable status, source index, and trial ledger, and state the exact next continuation point.','global','canonical','locked','SRC-COMPILE','research-process'),
('F-025','spatial',3,'Scene is compiled environment','A Scene is not a map image; it is a compiled environment containing dimensions, grid, Levels, placeables, links, environment, navigation, and initial view.','global','static','active','SRC-CHAT-COMPILER','scenes,maps'),
('F-026','spatial',4,'Graybox before artwork','Campaign-critical maps require authoritative spatial blueprint and deterministic graybox review before expensive image generation.','global','static','active','SRC-CHAT-COMPILER','maps,graybox'),
('F-027','automation',21,'No generated arbitrary code','Generated automation must be declarative, bounded, reviewed, exact-artifact tested, and free of eval/new Function/arbitrary remote code or raw database access.','global','canonical','locked','SRC-CHAT-MACRO','automation,safety'),
('F-028','links',32,'Two-pass linked creation','Create and verify destination documents before writing links, use exact UUID/runtime bindings, detect stale links, and guard against loops/bounce.','global','canonical','locked','SRC-REGION-DOSSIER','links,cross-scene'),
('F-029','media',31,'Approved asset reuse','Normal rebuilds reuse approved media by immutable hash; regeneration is explicit, provenance-aware, and validated for rights, dimensions, topology, alpha, and distribution.','global','canonical','locked','SRC-FOUNDATION','media,assets'),
('F-030','state',NULL,'Campaign truth versus runtime projection','Effects, Regions, audio, Tiles, and module state are projections or runtime state; quest and campaign knowledge truth remains in the DiceBox state model.','global','canonical','locked','SRC-COMPILE','state,ownership'),
('F-031','module',NULL,'Module manifest boundary','Foundry requires a root module.json whose id matches the module directory; ES modules, compatibility, relationships, manifest, and download metadata are package concerns from the first module slice.','global','static','active','SRC-GAP-RESEARCH','module,manifest,release'),
('F-032','transactions',34,'Batch limitation','Foundry modifyBatch can prevent partial commit for supported operations but cannot reference an ID created earlier within the same batch; dependent creation requires staged transactions.','global','static','active','SRC-GAP-RESEARCH','transactions,modifyBatch'),
('F-033','knowledge',NULL,'FTS rebuild boundary','An FTS5 external/content index must remain synchronized with source rows; the current DiceBox KB is compiled from schema and seed and does not assume live editing.','global','static','active','SRC-GAP-RESEARCH','sqlite,fts5'),
('F-034','activities',2,'Activity hook boundary','D&D5e exposes Activity lifecycle hooks, but DiceBox must inspect the actual registered Activity classes/hooks on the exact target runtime before capability promotion.','global','static','active','SRC-GAP-RESEARCH','dnd5e,activities,hooks'),
('F-035','implementation',35,'M0 contract spine','The M0 checkout contains four package boundaries, canonical schemas, a readiness-gated read-only bridge, and a no-op Foundry manifest/bootstrap; it does not claim live runtime or world-mutation evidence.','project','deterministic','active','SRC-M0-IMPLEMENTATION','m0,contracts,verification'),
('F-036','market',NULL,'Action HUD competition boundary','A standalone D&D5e Player Turn Coach competes with current Foundry HUDs, player-authored reminders, manual action tracking, and turn analytics; contextual ranking should remain a supporting feature rather than the first product thesis.','project','created_document','active','SRC-PRODUCT-RESEARCH','market,competition,player-coach'),
('F-037','market',NULL,'Session Rescue finalist','Campaign Continuity / Session Rescue is the current product finalist because it targets GM-paid disruption costsâ€”absent players, off-script play, and uncertain resumptionâ€”while reusing semantic state, provenance, staging, read-back, and recovery assets. It remains unvalidated until behavioral buyer evidence exists.','project','created_document','provisional','SRC-PRODUCT-RESEARCH','market,session-rescue,buyer-validation'),
('F-038','market',NULL,'Semantic branch gap','Foundry package snapshots and current document backup modules restore whole packages or named documents, while campaign-planning and AI co-pilot tools cover preparation or continuation. The research found no directly comparable current package advertising a typed session branch with selective semantic merge/discard; this absence is a research hypothesis, not proof of uniqueness.','project','created_document','provisional','SRC-CONTINUITY-PASS','market,branching,rollback,competition'),
('F-039','portability',NULL,'Neutral branch packet boundary','Foundry can support a previewable branch using serializable Document data, local validation, and supported create/update operations, but cross-document atomicity is not universal. Roll20 live Mods are creator/Pro-bound and Fantasy Grounds uses XML campaign state plus Lua/XML extensions; portability should therefore begin with read-only neutral branch packets and explicit adapters.','project','created_document','provisional','SRC-PORTABILITY-PASS','portability,foundry,roll20,fantasy-grounds,branching'),
('F-040','market',NULL,'Willingness-to-pay hypothesis','Foundry supports one-time premium modules, but Safe Mode is episodic and competes with free backups, notes, and planning tools. The most plausible buyer is a GM with persistent or paid weekly play; pricing should test a free checkpoint/export plus a $15â€“25 one-time protection layer. This is a falsifiable hypothesis, not observed purchase conversion.','project','created_document','provisional','SRC-PRICING-PASS','market,pricing,buyer,one-time'),
('F-041','market',NULL,'Safety moat is insufficient','Foundry backups, Recycle Bin, World CLI, Campaign Forge, and manual duplicate-world workflows cover adjacent recovery, live-edit, and campaign-state jobs. Campaign Safe Mode is defensible only if a typed session branch with semantic diff and selective merge/discard solves a real table decision better than those alternatives.','project','created_document','provisional','SRC-REJECTION-PASS','market,competition,branching,go-no-go'),
('F-042','market',NULL,'Player friction is real but saturated','Players report overloaded sheets, unintuitive rolls, stale or broken sheet state, onboarding difficulty, mobile/second-screen needs, and accessibility barriers. Current Foundry packages already cover much of the generic companion, mobile, navigation, inventory, and trading space, so player pain alone does not establish a new paid category.','project','created_document','provisional','SRC-PLAYER-PASS','market,players,competition,accessibility'),
('F-043','portability',NULL,'Neutral session packet is the portability wedge','Because VTTs expose different live-state and permission boundaries, cross-VTT portability should begin with a neutral read-only session packet and player-safe re-entry view. Foundry can be the first live adapter; universal live synchronization remains out of scope until explicit adapters prove equivalent behavior.','project','created_document','provisional','SRC-PLAYER-PASS','portability,cross-vtt,session-packet'),
('F-044','market',NULL,'Safe Mode has an invisible-insurance problem','Campaign Safe Mode is useful but is not naturally attention-grabbing in a marketplace where visual content and immediate player-facing outcomes dominate browsing. It must be presented as Campaign Continuity: a visible disruption-to-branch-to-merge outcome, not as generic safety infrastructure.','project','created_document','provisional','SRC-MARKETING-PASS','market,positioning,attention,branding'),
('F-045','market',NULL,'Desirability must be demonstrated without explanation','The candidate should be tested with a five-second thumbnail/clip and a thirty-second silent demo. It passes attention only if qualified GMs can identify the user, moment, and payoff and prefer it over a real backup, journal, or duplicate-world alternative.','project','created_document','provisional','SRC-MARKETING-PASS','market,go-no-go,demo,social-proof'),
('F-046','market',NULL,'Canon and Branch Board is the hero-artifact hypothesis','A visible campaign timeline, current branch lane, Keep/Discard semantic diff, player-safe Re-entry Card, and Canonize action can make Campaign Continuity glanceable while remaining grounded in the branch engine. It is not a validated product surface and must not degrade into a prettier recap or wiki.','project','created_document','provisional','SRC-HERO-ARTIFACT-PASS','market,positioning,ui,branching,go-no-go'),
('F-047','market',NULL,'Disruption pain is real but continuity purchase urgency is mixed','Absent-player and off-script problems can cause cancelled sessions, one-shots, ghosted characters, or campaign momentum loss, but groups often have workable social alternatives. The pain is not yet sufficient evidence for a paid branch product.','project','created_document','provisional','SRC-URGENCY-PASS','market,buyer-pain,continuity,urgency'),
('F-048','market',NULL,'Campaign Guardian is a stronger urgency challenger but not a clear winner','Update, migration, and data-loss failures create sharper game-night urgency and support a self-contained launchable save-state/preflight concept. Free Foundry backups, Recycle Bin, World CLI, and manual copies remain credible alternatives, so the challenger requires direct buyer comparison.','project','created_document','provisional','SRC-URGENCY-PASS','market,buyer,backup,preflight,challenger'),
('F-049','market',NULL,'Guardian, Replay, and improvisation suites are not standalone gaps','Foundry and Forge cover most save-state recovery, Battle Replay covers visual combat replay, and current modules cover encounter generation, improvisation, progressive events, and cinematic scene control. These should be treated as adjacent features or explicit alternatives, not new product directions.','project','created_document','provisional','SRC-REJECTION-23','market,competition,rejection,product-selection'),
('F-050','market',NULL,'Semantic non-combat selective canonization remains the narrow gap hypothesis','The remaining candidate is a typed branch across campaign state and non-combat Documents with player/GM visibility boundaries, selective merge, provenance, and recovery receipts. No current evidence proves buyers will pay for it, so it remains a testable hypothesis rather than a market conclusion.','project','created_document','provisional','SRC-REJECTION-23','market,branching,merge,provenance,go-no-go'),
('F-051','technical','40','Foundry API supports a narrow branch prototype','Foundry v14 exposes serializable Document source data, ephemeral clone, local update/validation, permission checks, create/update operations, and pre/post update hooks. These primitives are sufficient for a read-only checkpoint, preview diff, and GM-authorized staged merge prototype.','project','static','provisional','SRC-TECH-PASS','foundry,api,branch,preview,validation'),
('F-052','technical','40','Foundry does not provide universal transaction or state coverage','Differential updates, array replacement, staged dependent creation, module-owned state, external media, and cross-document failures prevent an assumption of atomic rollback. The implementation needs dependency ordering, idempotent receipts, authoritative reread, compensating recovery, and explicit unsupported-state handling.','project','static','provisional','SRC-TECH-PASS','foundry,transactions,recovery,scope'),
('F-053','market',NULL,'Foundry paid-product browse is visual and crowded','The current Foundry package index lists thousands of add-on modules and more than a thousand premium packages. Current product pages that compete for attention lead with screenshots, video, modern UI, or an immediate player-visible outcome. This establishes an attention standard, not a sales ranking.','project','static','provisional','SRC-ATTENTION-PASS','market,attention,competition,visual'),
('F-054','market',NULL,'Campaign Continuity fails the first storefront attention hypothesis','Safe Mode is invisible infrastructure for an episodic problem; Undo the Session creates retcon/trust concerns; Continue After a Disruption is clear but not immediately visual. Canon & Branch Board may be attractive but overlaps with current campaign dashboards, timelines, clue boards, and organizer surfaces.','project','created_document','provisional','SRC-ATTENTION-PASS','market,positioning,go-no-go,continuity'),
('F-055','market',NULL,'Adventure Capsules is the next product candidate','A short ready-to-run, player-visible session can show its value in a listing through scenes, handouts, reveals, bounded choices, and a finished evening. It offers a clearer GM payer, recurring capsule purchases, and a neutral content/export boundary, but it remains unvalidated and competes with premium adventures and map/content packs.','project','created_document','provisional','SRC-ATTENTION-PASS','market,adventure,capsules,content,portability'),
('F-056','market','40','Ready-to-run Foundry adventure content is a real paid category but is crowded','Current Foundry packages already offer minimal-prep, drop-in, one-session, animated, branching, and high-production adventures. This validates that GMs buy prepared content in principle, but it does not validate a new generic capsule.','project','static','provisional','SRC-ADVENTURE-PASS','market,adventure,competition,pricing'),
('F-057','market','40','Generic Adventure Capsules have no sufficient competitive gap','Drop-in Dungeons, Prepared! 2, Dragonshorn, Boss Loot, Rultmoork, and premium publishers already cover ready-to-run maps, handouts, music, choices, adjustable difficulty, and Foundry integration. Branching tools such as UO Scenario Branches and Visual Novel Maker further reduce the feature gap.','project','created_document','provisional','SRC-ADVENTURE-PASS','market,adventure,competition,branching'),
('F-058','market','40','Adaptive Drop-In Capsules are the narrowed candidate','A 60â€“120 minute no-canon session for variable attendance could target a recurring GM problem: preserving the scheduled social event when one or more players are absent without preparing or mutating the main campaign. This is only a hypothesis and must beat cancellation, ghosting, free PDFs, second worlds, and existing premium adventures in a real purchase-choice test.','project','created_document','provisional','SRC-ADVENTURE-PASS','market,attendance,drop-in,no-canon,buyer-test'),
('F-059','technical','34','Exact target Foundry runtime is locally available','The local machine contains Foundry 14.367, D&D5e 5.3.3, a readable regionwright-testmap fixture manifest, DiceBox Campaign Helper 0.1.2, and optional Midi-QOL/DAE manifests.','project','deterministic','provisional','SRC-RUNTIME-AVAILABILITY','foundry,runtime,versions,fixture'),
('F-060','technical','34','Manifest preflight does not certify live runtime behavior','The read-only preflight passed data path, world identity, Foundry version, D&D5e version, DiceBox package, and optional module manifest checks, but returned BLOCKED because the ready-hook/live probe was NOT_TESTED.','project','deterministic','provisional','SRC-RUNTIME-AVAILABILITY','foundry,preflight,evidence-boundary,not-tested'),
('F-061','market',NULL,'Foundry premium discovery is large but attention-constrained','The official Marketplace reports 1,227 products, 107 creators, 60,000 users, and 371 customer reviews after its first year, with filters for price, rating, publisher, tags, and verified version. This proves a meaningful discovery surface and a trust/attention burden, not product-level sales.','project','static','provisional','SRC-EYE-CATCHING-28','market,marketplace,discovery,attention,reviews'),
('F-062','market',NULL,'Omnipresence closes part of the Adaptive Drop-In gap','Omnipresence explicitly supports keeping characters, journals, and hotbars synchronized across Foundry worlds and names one-shot campaigns as a use case. A new product cannot differentiate on cross-world character continuity alone; it must sell the finished attendance-rescue experience and clean return.','project','static','provisional','SRC-EYE-CATCHING-28','market,competition,attendance,one-shot,omnipresence'),
('F-063','market',NULL,'Game Night Rescue is the sharper front-door message','The trigger-based promise â€œOne player canceled. Donâ€™t cancel the game.â€ makes the Adaptive Drop-In Capsule more immediately legible than Safe Mode or Campaign Continuity. It remains a hypothesis until qualified buyers choose it over cancellation, a free PDF, a premium one-shot, a second world, or no purchase.','project','created_document','provisional','SRC-EYE-CATCHING-28','market,positioning,attention,attendance,buyer-test'),
('F-064','market',NULL,'The storefront product must be content plus workflow','A visual capsule alone is another ready-made adventure, while the branch engine alone is invisible infrastructure. The provisional paid unit is an original 60â€“120 minute capsule plus present-player selection, explicit no-canon status, safe exit, and player-safe return packet; Campaign Continuity remains reusable backend infrastructure.','project','created_document','provisional','SRC-EYE-CATCHING-28','market,productization,capsule,no-canon,workflow'),
('F-065','market',NULL,'Official distribution adds rights and marketing constraints','Foundry recommends Adventure Compendium Packs for complicated premium content, and its current AI policy requires prepared user-facing text, media, and marketing materials for official listings to originate from human creative work. A rights-clean original capsule is therefore a safer product path than an automatically generated content catalog.','project','static','provisional','SRC-EYE-CATCHING-28','market,packaging,rights,ai-policy,content'),
('F-066','market',NULL,'Home-table attendance pain has low default willingness to pay','Community reports show real absences and cancellations, but many home tables solve them with quorum rules, background characters, backup pilots, duplicate worlds, free one-shots, or rescheduling. The event is common enough to research but not yet a mass-market paid problem.','project','static','provisional','SRC-PAYER-SEGMENT-29','market,attendance,home-gm,payment,alternatives'),
('F-067','market',NULL,'Paid and organized GMs have the clearest economic buyer case','Published professional-GM offerings sell recurring sessions per player, packages, or booked events and may bill late cancellations or lose booking value. This gives Game Night Rescue a measurable ROI hypothesis around protecting prep, revenue, retention, and scheduled play, but does not prove module purchase intent.','project','static','provisional','SRC-PAYER-SEGMENT-29','market,payer,paid-gm,roi,attendance'),
('F-068','market',NULL,'West Marches and rotating hosts are attractive but already served operationally','Oronder explicitly targets West Marches and single-party campaigns with Discord access, scheduling, and cross-world character support. The remaining candidate must sell the finished no-canon session and safe exit rather than generic scheduling or synchronization.','project','static','provisional','SRC-PAYER-SEGMENT-29','market,competition,west-marches,oronder,attendance'),
('F-069','market',NULL,'Game Night Rescue should be tested first with a payer-specific message','The strongest untested message is â€œProtect the booked game night when attendance changes,â€ aimed at paid/professional GMs and high-variance organizers. Home GMs remain useful for usability evidence, but their reactions cannot establish willingness to pay for the product.','project','created_document','provisional','SRC-PAYER-SEGMENT-29','market,positioning,payer,buyer-test,roi'),
('F-070','product',NULL,'DMF is an end-to-end item and automation compiler','The local DMF project accepts natural-language item requests, compiles native D&D5e item specifications, repairs known schema/activity/targeting/resource/effect/summon issues, presents review findings, and attaches capability-gated Midi-QOL, DAE, or Item Macro routes when supported.','project','deterministic','active','SRC-DMF-MARKET-30','dmf,item-compiler,automation,review,foundry,dnd5e'),
('F-071','market',NULL,'DMF has a credible gap beyond plain-language item generation','D&D Item Auto Maker publicly emphasizes plain-English item generation and fully-statted Foundry documents with JSON export, while DMF additionally targets cross-module automation compilation and verification. This is a differentiation hypothesis, not buyer proof.','project','static','provisional','SRC-DMF-MARKET-30','dmf,competition,automaker,item-creation,midi-qol'),
('F-072','market',NULL,'The strongest DMF payer hypothesis is the automation-heavy D&D5e GM','Community requests show recurring difficulty wiring conditional damage, effects, charges, timing, Midi-QOL hooks, DAE, and Item Macro behavior. Simple-item GMs have cheaper alternatives, so broad willingness to pay remains unproven.','project','static','provisional','SRC-DMF-MARKET-30','dmf,buyer,automation-heavy-gm,willingness-to-pay'),
('F-073','product',NULL,'Custom Item Workshop is the buyer-facing DMF hypothesis','â€œMake the homebrew item work, not just existâ€ presents DMF as a reviewed compiler that creates the item, explains dependencies, and supplies a verification receipt. It must beat native forms, Auto Maker, Item Creator, free macros, and community help.','project','created_document','provisional','SRC-DMF-MARKET-30','dmf,custom-item-workshop,positioning,buyer-test'),
('F-074','portability',NULL,'DMF portability belongs at the recipe and receipt layer','Reviewed item recipes, dependency declarations, assumptions, and verification receipts can be exported or re-rendered for another VTT, but Foundry Item documents and Midi-QOL hooks are platform-specific projections.','project','static','provisional','SRC-DMF-MARKET-30','dmf,portability,recipe,receipt,vtt'),
('F-075','market',NULL,'Automaker establishes the direct-item speed baseline','The current D&D Item Auto Maker public package and source provide a short-description builder, direct world insertion, history/retry, JSON export, Patreon authentication, and monthly generation allowance. Its public surface does not advertise Midi-QOL/DAE/Item Macro wiring.','project','static','provisional','SRC-AUTOMAKER-COMPARE-31','automaker,competition,item-creation,monetization'),
('F-076','market',NULL,'DMF should differentiate on automation completion, not basic generation speed','Automaker is a credible baseline for simple items. DMF''s defensible wedge is compiling and verifying the cross-module behavior of unusual items while preserving a fast core-only fallback.','project','created_document','provisional','SRC-AUTOMAKER-COMPARE-31','dmf,automaker,positioning,automation,midi-qol'),
('F-077','market',NULL,'Usage monetization is plausible but not sales proof','Automaker''s source uses Patreon authentication and monthly generation allowances, showing a viable monetization design for an AI Foundry utility. No public evidence here establishes its conversion, retention, or revenue.','project','static','provisional','SRC-AUTOMAKER-COMPARE-31','monetization,patreon,usage,market-evidence'),
('F-078','buyer',NULL,'The decisive DMF test is behavioral setup saved on a complex item','A side-by-side test must measure manual edits, module settings, working behavior, time to first usable item, and a real price choice. A simple generated core item is not enough to prove DMF value.','project','created_document','provisional','SRC-AUTOMAKER-COMPARE-31','dmf,buyer-test,complex-item,setup-time,willingness-to-pay'),
('F-079','portability',NULL,'Foundry item automation is system-native','D&D5e Activities and the Item document model are Foundry/D&D5e-native. Midi-QOL, DAE, and Item Macro add Foundry-specific runtime behavior, so their compiled outputs cannot be treated as universal VTT artifacts.','project','static','provisional','SRC-DMF-PORTABILITY-32','dmf,foundry,activities,midi-qol,dae,item-macro,portability'),
('F-080','portability',NULL,'Roll20 and Fantasy Grounds require separate projections','Roll20 Mod/API scripts are campaign-local and Pro-gated, while Fantasy Grounds uses built-in ruleset automation and separate XML/Lua extension or ruleset customization. Neither shares Foundry''s document/module contract.','project','static','provisional','SRC-DMF-PORTABILITY-32','roll20,fantasy-grounds,api,xml,lua,portability'),
('F-081','product',NULL,'The portable DMF boundary is a recipe and receipt','Intent, assumptions, activity/triggers, resource use, dependencies, unresolved clauses, approvals, test cases, and verification receipts can be exported neutrally even when runtime automation is platform-specific.','project','created_document','provisional','SRC-DMF-PORTABILITY-32','dmf,recipe,receipt,neutral,export'),
('F-082','market',NULL,'Portability is a differentiator only if it does not dilute the Foundry wedge','A neutral export may widen the buyer pool, but each live VTT projection multiplies capability, licensing, compatibility, and support work. Foundry automation must remain the reason to pay for the first release.','project','static','provisional','SRC-DMF-PORTABILITY-32','dmf,market,portability,support,willingness-to-pay'),
('F-088','market',NULL,'Foundry upgrade breakage is a broad recurring GM pain','A highly engaged current community discussion describes major releases as a gamble involving broken modules, changed workflows, stale documentation, and paid content that may become unusable until dependencies catch up. This is pain evidence, not purchase proof.','project','static','provisional','SRC-UPGRADE-GUARDIAN-34','foundry,updates,breakage,gm,pain'),
('F-089','product',NULL,'The upgrade gap is preflight and rehearsal, not backup alone','Foundry provides backups, snapshots, compatibility metadata, and package update controls. The unserved hypothesis is a world-specific report plus disposable clone and critical-path smoke tests that reveal behavioral failure before the live world is migrated.','project','static','provisional','SRC-UPGRADE-GUARDIAN-34','upgrade,preflight,rehearsal,backup,smoke-test'),
('F-090','competition',NULL,'Existing compatibility and configuration tools leave a behavior-testing gap','Module Compatibility Checker is old and metadata-oriented; Module Profiles, Module Loadouts, Settings Vault, and Content Backup & Restore preserve or restore state but do not rehearse a campaign''s actual workflows on the candidate stack.','project','static','provisional','SRC-UPGRADE-GUARDIAN-34','competition,compatibility,profiles,settings,backup'),
('F-091','market',NULL,'Upgrade Guardian has a stronger ordinary-GM front door than DMF','The promise â€œknow what will break before you updateâ€ addresses the GM responsible for an active campaign, produces a visible red/amber/green result, and recurs with core/system/module releases.','project','created_document','provisional','SRC-UPGRADE-GUARDIAN-34','upgrade-guardian,ordinary-gm,positioning,eye-catching'),
('F-092','technical',NULL,'Upgrade Guardian cannot honestly promise universal safety','Static metadata misses runtime breakage, and a disposable clone may not cover every workflow. The product must report observed, known, and untested areas and never turn a green result into a guarantee.','project','canonical','provisional','SRC-UPGRADE-GUARDIAN-34','upgrade,testing,evidence,trust,limitations'),
('F-093','portability',NULL,'Upgrade safety is Foundry-first with a portable report model','The package/dependency/health-report abstraction can later support other plugin-rich VTTs, but live clone and smoke-test adapters will be platform-specific. Cross-VTT support is an extension path, not an initial promise.','project','static','provisional','SRC-UPGRADE-GUARDIAN-34','portability,foundry,report,adapter'),
('F-094','technical',NULL,'Upgrade Guardian needs a local companion boundary','A world-running module should not copy its own open database, replace the active Foundry executable, or claim to rehearse a future stack in place. A local companion can operate at setup time and launch a closed-world disposable rehearsal.','project','created_document','provisional','SRC-UPGRADE-TECH-35','upgrade,companion,local,clone,architecture'),
('F-095','technical',NULL,'Foundry metadata supports static preflight but not behavioral certification','Package manifests expose compatibility, dependencies, and version history, while user-data and backup APIs provide the inputs for snapshots. These signals cannot prove that a selected campaign workflow will work after migration.','project','static','provisional','SRC-UPGRADE-TECH-35','upgrade,metadata,compatibility,preflight,evidence'),
('F-096','licensing',NULL,'The safe distribution boundary is user-owned installation inspection','Upgrade Guardian can inspect manifests and user-owned files, invoke the user''s installed Foundry, and store local reports, but should not redistribute Foundry, paid modules, rulebook text, art, or campaign assets.','project','static','provisional','SRC-UPGRADE-TECH-35','licensing,foundry,premium-content,local,rights'),
('F-097','technical',NULL,'Upgrade rehearsal has material false-confidence risks','A disposable clone may require disk space, closed processes, online entitlements, and copies of external module-owned state; unselected workflows remain untested. Reports need explicit metadata-compatible, probe-passed, probe-failed, not-exercised, and restore-verified states.','project','created_document','provisional','SRC-UPGRADE-TECH-35','upgrade,clone,smoke-test,trust,false-confidence'),
('F-098','product',NULL,'Upgrade Guardian is a local companion plus optional probe','The first product should not be a self-modifying in-world module or a cloud service. Its credible boundary is a Windows/local setup companion, disposable rehearsal world, optional Foundry probe, and evidence-labeled report viewer.','project','created_document','provisional','SRC-UPGRADE-TECH-35','upgrade-guardian,companion,probe,foundry,windows'),
('F-099','competition',NULL,'Foundry already covers generic pre-update compatibility and rollback','Foundry''s pre-update compatibility check, built-in backups/snapshots, portable builds, and documented multi-version installation address the basic compatibility and recovery jobs. A new product cannot sell those capabilities alone.','project','static','provisional','SRC-RUNTIME-LOCKER-36','foundry,compatibility,backup,portable,competition'),
('F-100','market',NULL,'Hosting services monetize operational risk reduction','The Forge and VTT Online sell ongoing hosting with automatic backups and version choice, providing a paid alternative to self-managed runtime safety. Their existence is market evidence for the problem but also a direct competitive benchmark.','project','static','provisional','SRC-RUNTIME-LOCKER-36','hosting,pricing,backup,version-switching,competition'),
('F-101','buyer',NULL,'Many GMs solve upgrade risk by waiting or maintaining a manual test install','Community reports describe delaying upgrades during active campaigns, keeping an old version, or testing modules one at a time in a separate installation. This validates pain but supplies a low-cost workaround that a paid tool must beat.','project','static','provisional','SRC-RUNTIME-LOCKER-36','buyer,workaround,upgrade,manual,test-install'),
('F-102','market-selection',NULL,'A generic Upgrade Guardian report is not yet a paid product','Core compatibility checks and backups reduce the novelty of a red/amber/green dashboard. The remaining purchase hypothesis is local per-world runtime locking, one-click known-good launch, and optional upgrade rehearsal for self-hosters or multi-world GMs.','project','created_document','provisional','SRC-RUNTIME-LOCKER-36','upgrade-guardian,runtime-locker,market-selection,self-hosting'),
('F-103','pricing',NULL,'Campaign Runtime Locker must beat hosting and manual installs','A one-time local price is credible only if self-hosters value control and reproducibility enough to reject low-cost hosting with version switching and snapshots. Price choice has not been observed.','project','created_document','provisional','SRC-RUNTIME-LOCKER-36','runtime-locker,pricing,willingness-to-pay,hosting'),
('F-104','market',NULL,'Player-facing Foundry lag is recurring and difficult to localize','Current community reports describe slow sheets, delayed chat, low frame rates, long-session degradation, and some players being unable to join or play. The reported causes span client hardware, browser/GPU settings, network conditions, asset load, chat size, scene complexity, and module interactions, so the symptom is visible while the cause is often unclear.','project','static','provisional','SRC-SESSION-HEALTH-37','foundry,performance,player-lag,diagnostics,pain'),
('F-105','competition',NULL,'Foundry already has strong point solutions for performance','Axon''s Performance Monitor provides live monitoring, scene/module diagnostics, benchmarks, reports, and recommendations; Performance Optimizer provides per-player profiles, GM controls, low-FPS warnings, and a benchmark; Prime Performance optimizes token UI rendering; and Find the Culprit automates module bisection. A generic FPS dashboard or optimizer would be a weak product.','project','static','provisional','SRC-SESSION-HEALTH-37','competition,performance-monitor,optimizer,find-the-culprit'),
('F-106','product-gap',NULL,'The remaining performance gap is correlated incident diagnosis','The checked tools expose metrics, apply client profiles, optimize a rendering path, or isolate modules. No evidence in this pass establishes a single product that correlates per-player FPS/latency/browser-GPU signals with scene assets, module events, and server timeline, then gives the GM a reproducible next action without blindly disabling half the world. This is a hypothesis, not a proven whitespace.','project','created_document','provisional','SRC-SESSION-HEALTH-37','performance,correlation,incident-response,diagnosis,hypothesis'),
('F-107','product',NULL,'The eye-catching candidate is Session Health Autopsy','The buyer-facing promise would be â€œFind who is lagging and why before game night,â€ followed by a short guided capture: identify affected clients, reproduce the symptom in a disposable or low-risk scene, correlate asset/module/browser signals, and produce a ranked action plan plus a reversible degraded-session profile.','project','created_document','provisional','SRC-SESSION-HEALTH-37','session-health,lag-autopsy,positioning,eye-catching'),
('F-108','buyer',NULL,'The likely payer is the GM responsible for a disrupted table','Players feel the pain, but the GM or host controls the module stack and is the person who loses session time, receives support requests, and decides whether to pay. A purchase case requires a recent incident that cost meaningful play time or threatened a session; general dislike of lag is not willingness-to-pay evidence.','project','created_document','provisional','SRC-SESSION-HEALTH-37','buyer,gm,payer,session-disruption,willingness-to-pay'),
('F-109','portability',NULL,'Performance evidence can have a portable report boundary','A neutral session-health record can represent client capability, scene/asset budget, event timestamps, latency/FPS samples, suspected cause, confidence, and recommended action. Collection and safe remediation remain VTT-specific because Foundry, Roll20, and other platforms expose different client and module boundaries.','project','created_document','provisional','SRC-SESSION-HEALTH-37','portability,health-record,report,adapter'),
('F-110','technical',NULL,'A credible diagnosis product must protect the live session','The first implementation should collect consented local/client metrics, avoid uploading raw chat or campaign content, support a disposable reproduction scene or read-only trace, label correlation as suspicion rather than proof, and apply only reversible profile changes. A â€œgreenâ€ performance result cannot certify every device or module combination.','project','created_document','provisional','SRC-SESSION-HEALTH-37','technical,privacy,reversible,foundry,trust'),
('F-111','market-selection',NULL,'Generic performance tooling is rejected; guided incident response remains conditional','The category has active and recently updated competitors, so the product is not selected on the existence of lag alone. It remains worth a buyer test only if affected GMs prefer a guided cross-client diagnosis and reversible session profile over existing tools, support posts, module bisection, or simply asking players to lower settings.','project','created_document','provisional','SRC-SESSION-HEALTH-37','market-selection,competition,performance,buyer-test'),
('F-112','market',NULL,'Mobile and low-end player access is a real Foundry pain','Foundry''s own FAQ says mobile devices are not supported by the core software. Current community reports describe players on old laptops, phones, tablets, or unsupported browsers being unable to join or play, with screen sharing or a different VTT used as the fallback.','project','static','provisional','SRC-MOBILE-RELAY-38','foundry,mobile,low-end,accessibility,player-pain'),
('F-113','competition',NULL,'The Foundry mobile companion category is already active','Swipe VTT, Sheet Only, Foundry Tabletop Helpers, Companion Bridge/VTT Companion, and PocketScroll already offer some combination of touch controls, mobile sheets, chat, maps, combat, rolls, or GM controls. PocketScroll uses a GM subscription with free player invite links, while other products use free/core plus Patreon or premium features.','project','static','provisional','SRC-MOBILE-RELAY-38','competition,mobile,companion,pricing,foundry'),
('F-114','market',NULL,'Roll20 is investing in the same player-side direction','Roll20 retired its old mobile app in favor of a browser-first character experience and reports phone-ready D&D sheets with synchronized rolls/actions. This validates demand for a focused player surface but also creates a strong platform-level competitor for cross-VTT ambitions.','project','static','provisional','SRC-MOBILE-RELAY-38','roll20,mobile,browser,competition,player-surface'),
('F-115','market-selection',NULL,'A generic mobile companion is a no-go','A new phone character sheet, touch map, or companion app would overlap multiple current offerings and would inherit app-store, authentication, system-adapter, and Foundry-version support costs. Mobile pain alone does not justify another paid companion.','project','created_document','provisional','SRC-MOBILE-RELAY-38','mobile,market-selection,competition,no-go'),
('F-116','product-gap',NULL,'Only a low-bandwidth browser relay remains a conditional wedge','A narrower product could avoid full-canvas rendering and app installation: the GM shares a short invite, and an ordinary browser exposes the player''s current character actions, rolls, chat, turn state, and a deliberately lightweight map/position view. It would need to beat PocketScroll''s invite flow and existing mobile modules on device reach, setup, and resource use.','project','created_document','provisional','SRC-MOBILE-RELAY-38','mobile,low-bandwidth,browser,relay,product-gap'),
('F-117','portability',NULL,'A player-relay protocol is portable only at the action boundary','Character summary, turn state, dice request, chat, and lightweight scene packets can be represented neutrally. Rules resolution, permissions, movement, effects, and inventory writes still require separate adapters for Foundry, Roll20, and other VTTs.','project','created_document','provisional','SRC-MOBILE-RELAY-38','portability,protocol,adapter,player-actions'),
('F-118','buyer',NULL,'The mobile player problem has explicit non-zero price anchors','In a current Foundry companion discussion, players describe the wall of laptops and state that they would pay roughly â‚¬20â€“â‚¬25 for a useful phone experience; another participant names a lower one-time price as an immediate purchase. This is directional self-reported intent from one product thread, not representative conversion data.','project','static','provisional','SRC-PAYER-MOBILE-39','buyer,mobile,price,willingness-to-pay'),
('F-119','monetization',NULL,'Current companions demonstrate viable payment shapes','VTT Companion offers a â‚¬15 one-time Lifetime Link for its D&D5e premium module with optional subscriptions, while PocketScroll uses a GM subscription and free player invite links. These are evidence that a GM-paid, table-wide device utility can be monetized, not evidence of their sales or retention.','project','static','provisional','SRC-PAYER-MOBILE-39','monetization,one-time,subscription,gm-payer,mobile'),
('F-120','competition',NULL,'The full mobile companion surface is already closed by a direct competitor','VTT Companion advertises a sub-5MB app, real-time sync, offline cached sheets, phone actions, Foundry v13/v14 support, and a one-time premium module. It also states that system-specific modules are needed for different systems. A new full mobile character app would have no obvious reason to win.','project','static','provisional','SRC-PAYER-MOBILE-39','competition,vtt-companion,mobile,offline,foundry,dnd5e'),
('F-121','buyer',NULL,'Hybrid in-person groups are a visible payer segment','The companion discussion is driven by a concrete table problem: a GM projects the table while players need sheet interaction, and a laptop for every player crowds the physical table. The likely buyer is the GM who can buy one module for the group, while the player benefit supplies adoption pressure.','project','static','provisional','SRC-PAYER-MOBILE-39','buyer,hybrid,in-person,gm,tabletop'),
('F-122','product-gap',NULL,'The remaining candidate is a thin client, not a mobile companion','A defensible wedge would be a browser/PWA relay that avoids full Foundry canvas rendering and app-store installation, sends only current actions/rolls/chat/turn state plus a lightweight map or position view, and is designed for weak devices and low bandwidth. No checked evidence proves that this boundary beats the existing apps.','project','created_document','provisional','SRC-PAYER-MOBILE-39','thin-client,low-bandwidth,browser,pwa,product-gap'),
('F-123','pricing',NULL,'A first thin-client price test can use a â‚¬15â€“â‚¬25 GM-paid anchor','The observed one-time companion price and self-reported â‚¬20â€“â‚¬25 willingness-to-pay justify testing a GM-paid one-time range around â‚¬15, â‚¬20, and â‚¬25. They do not justify setting a final price or assuming that device reach is worth recurring payment.','project','created_document','provisional','SRC-PAYER-MOBILE-39','pricing,price-test,gm-payer,one-time'),
('F-124','technical',NULL,'Thin-client feasibility depends on a bounded action gateway','Foundry can remain the authority for permissions, Activities, Midi-QOL workflows, effects, movement, and inventory. The relay should send typed requests to the Foundry adapter and receive verified results; it should not duplicate rules or write directly from an untrusted player client.','project','created_document','provisional','SRC-PAYER-MOBILE-39','technical,foundry,authority,activities,midi-qol,relay'),
('F-125','licensing',NULL,'A local-first relay can avoid content redistribution risk','The relay can operate on the user''s running Foundry world and transmit only consented state needed for the active player view. It should not bundle D&D books, protected art, premium content, or a cloud copy of campaign data. Cross-VTT adapters would need their own capability and licensing review.','project','created_document','provisional','SRC-PAYER-MOBILE-39','licensing,privacy,local-first,cross-vtt'),
('F-126','technical',NULL,'Foundry provides a module-scoped socket boundary','The official module-development guidance allows a module to request a specialized socket namespace; the server relays arbitrary packets on module.{name} to connected clients. This supports a Foundry-mediated request/result channel, but does not by itself define a standalone browser client or its authentication.','global','static','provisional','SRC-THINCLIENT-TECH-40','foundry,socket,module,relay'),
('F-127','technical',NULL,'The public API is safer than private client internals','The v14 API documentation distinguishes a supported Public API from private or unclear surfaces and lists SocketInterface as the standardized helper for dispatching socket events. A product should stay within documented module, hook, socket, document, and permission boundaries and fail closed when a capability is unclear.','global','static','provisional','SRC-THINCLIENT-TECH-40','foundry,public-api,socket,safety'),
('F-128','security',NULL,'Foundry permissions can constrain relay-visible state and actions','Foundry separates role permissions from document permissions, and document ownership controls whether a user can view or edit particular Actors, Items, Journals, and other documents. A relay must authenticate as a Foundry user and project only the state that user may see; typed actions still require server-side capability and ownership checks.','global','static','provisional','SRC-THINCLIENT-TECH-40','permissions,ownership,privacy,player'),
('F-129','architecture',NULL,'A local-first thin client is plausible but not yet proven as a separate PWA','Because Foundry is a self-hosted web framework with connected clients and a module socket boundary, a narrow relay could be delivered through the user''s running Foundry instance without a separate cloud control plane. This is an architectural inference, not proof that an external PWA can join, authenticate, reconnect, or perform actions on the exact target stack.','project','created_document','provisional','SRC-THINCLIENT-TECH-40','local-first,pwa,self-hosted,unverified'),
('F-130','licensing',NULL,'The relay must avoid republishing protected content','Foundry''s licensing guidance requires rights for included rules text, artwork, icons, music, and other distributed content; code that changes core behavior is generally a safer module boundary. The thin client should transmit consented live state from the customer''s world rather than ship books, premium assets, or a hosted campaign copy.','global','static','provisional','SRC-THINCLIENT-TECH-40','licensing,content,privacy,foundry'),
('F-131','portability',NULL,'Cross-VTT portability belongs at the packet and capability layer','Foundry''s module/socket/document model is not evidence that Roll20, Fantasy Grounds, or another VTT exposes the same runtime authority or permissions. A neutral player-action packet and receipt can be portable, while each live adapter must separately verify authentication, permissions, actions, and unsupported behavior.','project','created_document','provisional','SRC-THINCLIENT-TECH-40','cross-vtt,packet,capability,adapter'),
('F-132','buyer-pain',NULL,'Foundry player friction includes repeated navigation and choice overload','Current community reports describe players who still struggle after months with sheet tabs, targeting, icons, multiple action surfaces, and basic controls; some players report leaving or preferring a simpler VTT. Other users dispute the severity, so this is a recurring pain signal rather than universal demand.','project','static','provisional','SRC-PLAYER-FLOW-41','player,ux,choice-overload,onboarding'),
('F-133','competition',NULL,'Existing packages cover slices of player-flow simplification','Foundry Navigator provides keyboard-first and screen-reader-oriented navigation for D&D5e v13/v14; Accessibility Enhancements adds drag/drop alternatives and audio feedback; Stylish Action HUD provides party cards and quick actions; party-inventory tools simplify shared loot. A generic HUD or accessibility patch is therefore not an open product category.','project','static','provisional','SRC-PLAYER-FLOW-41','competition,hud,accessibility,navigation,inventory'),
('F-134','product-gap',NULL,'Adding another HUD can increase the problem it claims to solve','Recent player-friction reports describe multiple interfaces, HUD bloat, duplicate action locations, and uncertainty about which control is correct. The wedge must reduce visible choices and guide the next task rather than add another permanent toolbar.','project','static','provisional','SRC-PLAYER-FLOW-41','ux,hud,bloat,choice,player'),
('F-135','product-gap',NULL,'Player Flow / Tabletop Ease Mode is a narrower alternate hypothesis','A per-player cockpit could show only the current task, legal/useful actions, relevant resources, target guidance, and a clear next step, with text labels and keyboard/screen-reader paths. It would hide irrelevant sheet surfaces and use Foundry as the authority instead of duplicating rules. No evidence yet proves it reduces table time or beats existing HUDs.','project','created_document','provisional','SRC-PLAYER-FLOW-41','player-flow,cockpit,guidance,accessibility,foundry'),
('F-136','buyer',NULL,'The likely payer is the GM buying reduced table friction','A GM can value fewer â€œwhere do I click?â€ interruptions, faster onboarding, and more independent players, but the current evidence is frustration and task failure rather than a price commitment. Buyer authority, session-frequency benefit, and non-zero price must be tested directly.','project','created_document','provisional','SRC-PLAYER-FLOW-41','buyer,gm,friction,onboarding,price'),
('F-137','portability',NULL,'Player-flow portability is strongest at the task-graph layer','A neutral task description such as choose action, choose target, confirm roll, spend resource, or resolve result could map to multiple VTTs. The UI, permissions, sheet schema, and live action execution remain platform- and system-specific.','project','created_document','provisional','SRC-PLAYER-FLOW-41','cross-vtt,task-graph,capability,adapter'),
('F-138','market-positioning',NULL,'The eye-catching promise is independent play, not another interface','The candidate should demonstrate a confused player completing the next correct action without opening a full sheet or waiting for GM instructions. That â€œfrom stuck to playingâ€ moment is more legible than accessibility infrastructure, but it must be compared with existing HUDs and simple player training.','project','created_document','provisional','SRC-PLAYER-FLOW-41','marketing,player,independence,attention'),
('F-139','competition',NULL,'Foundry already provides a free player-onboarding baseline','The official Player Orientation tutorial covers joining, claiming characters, learning the interface, opening sheets, and moving on the map; the broader knowledge base and GM tutorials cover additional setup. A generic onboarding product must beat material that is already available at no extra cost.','global','static','provisional','SRC-PLAYER-FLOW-42','onboarding,tutorial,free,competition,foundry'),
('F-140','buyer-behavior',NULL,'Groups commonly solve player confusion with instruction rather than purchase','Current community advice includes a dedicated learning session, a small tutorial campaign that introduces one module at a time, screen sharing, and existing HUDs or sheet simplification. These alternatives reduce the urgency for a standalone player-flow purchase.','project','static','provisional','SRC-PLAYER-FLOW-42','training,onboarding,substitute,community'),
('F-141','monetization',NULL,'Instruction can be monetized when bundled with valuable content','The paid Pathfinder Beginner Box explicitly teaches both the game and Foundry features while delivering a complete adventure. This supports bundling onboarding into premium content, not pricing a generic player tutorial or cockpit by itself.','project','static','provisional','SRC-PLAYER-FLOW-42','beginner-box,content,bundle,monetization'),
('F-142','market-selection',NULL,'Player Flow lacks direct willingness-to-pay evidence as a standalone product','The research found recurring confusion and accessibility pain but no direct buyer price choice for a generic cockpit; free tutorials, training, existing HUDs, and simpler VTT alternatives are credible substitutes. Standalone product selection is therefore unsupported.','project','created_document','provisional','SRC-PLAYER-FLOW-42','willingness-to-pay,rejection,substitute,player-flow'),
('F-143','product-architecture',NULL,'Player Flow should remain a reusable feature boundary','Task graphs, contextual guidance, labels, keyboard paths, and result receipts remain valuable components for a thin relay or content product. They should not create a second standalone product scope unless a future buyer test produces direct payment evidence.','project','created_document','provisional','SRC-PLAYER-FLOW-42','reusable-assets,task-graph,thin-client,feature'),
('F-144','buyer-signal',NULL,'Foundry users report a recurring desire for better drawing and whiteboard tools','Recent community discussions ask for better drawing and text controls, collaborative layers, and an Excalidraw-like experience; one participant explicitly frames the improvement as worth paying for. This is a demand signal, not observed conversion.','project','static','provisional','SRC-DRAWING-43','drawing,whiteboard,community,demand'),
('F-145','competition',NULL,'Generic Foundry drawing is already a populated category','Native Foundry drawings plus Precise Drawing Tools, Alternative Drawing Tools, Better Text Drawings, Wayfinder Wall Control, Dungeon Draw, Owlbear, and Miro cover much of the obvious freehand, text, wall, collaboration, and export surface.','project','static','provisional','SRC-DRAWING-43','drawing,competition,whiteboard,foundry,owlbear,miro'),
('F-146','competition',NULL,'MapForge is a current paid Foundry map-studio competitor','MapForge is listed for current Foundry v14 and combines asset libraries, floors, textures, paths, walls, doors, windows, lighting, atmosphere, prefabs, animation, and flatten/export workflows. It materially closes the paid â€œbetter visual map authoringâ€ gap.','project','static','provisional','SRC-DRAWING-43','mapforge,competition,paid,foundry,maps'),
('F-147','market-selection',NULL,'Generic drawing and whiteboard should be rejected as a standalone product','The demand is credible, but a new module would need to displace native tools, several active modules, Owlbear, Miro, and MapForge. A map-to-playable-geometry or package-completeness audit is a narrower creator feature, not the requested wide player market.','project','created_document','provisional','SRC-DRAWING-43','market-selection,rejection,drawing,geometry,audit'),
('F-148','rules-hook',NULL,'The 2024 D&D Study action makes creature knowledge an ordinary play hook','Official 2024 rules define Study as an action for making Intelligence checks about memory, books, clues, and knowledge across Arcana, History, Investigation, Nature, and Religion. The rules do not themselves provide a persistent VTT knowledge workflow.','global','static','provisional','SRC-MONSTER-GUIDE-44','dnd5e,study,knowledge,rules-hook'),
('F-149','buyer-pain',NULL,'Creature knowledge disputes create a recurring player and GM problem','Community discussions repeatedly address what a character should know about a creature, how to avoid player metagaming, and how to reveal useful lore without handing over a complete statblock. The incidence and payment value still require direct GM validation.','project','static','provisional','SRC-MONSTER-GUIDE-44','monster-knowledge,metagaming,lore,gm,player'),
('F-150','competition',NULL,'ANewFoe proves the D&D5e concept but has an older support trail','ANewFoe hides unknown monsters, tracks known creatures per player, changes token presentation, reveals information after identification, and supports GM approval/DC modifiers. Its listing targets Foundry 12+ and shows older v12 verification/update evidence, so it is category proof rather than current v14 certification.','project','static','provisional','SRC-MONSTER-GUIDE-44','anewfoe,competition,dnd5e,foundry,stale'),
('F-151','competition',NULL,'PF2E Bestiary Tracking validates selective bestiary reveal on current Foundry','PF2E Bestiary Tracking is a current Foundry v14 package with GM/player bestiary views and selective information reveal. It validates buyer value in one system while demonstrating that D&D5e and PF2e data/permissions need separate adapters.','project','static','provisional','SRC-MONSTER-GUIDE-44','pf2e,bestiary,tracking,reveal,competition'),
('F-152','product-gap',NULL,'Monster Field Guide has a distinct player-facing promise','The working promise is â€œYour character knows, even when you do notâ€: an unknown silhouette or alias becomes a player-safe field-guide entry after Study or evidence, rather than exposing a generic statblock or adding another permanent HUD.','project','created_document','provisional','SRC-MONSTER-GUIDE-44','monster-field-guide,creature-codex,marketing,player'),
('F-153','product-surface',NULL,'Tiered reveal and provenance make the candidate more than a bestiary viewer','A useful record can separate identity/type/behavior, visible traits, resistances/weaknesses, and deeper lore, while recording evidence such as a check, observed regeneration, book research, GM approval, uncertainty, or rumor.','project','created_document','provisional','SRC-MONSTER-GUIDE-44','reveal-tier,evidence,provenance,uncertainty,codex'),
('F-154','buyer',NULL,'The likely payer is a GM with repeated knowledge-heavy play','Mystery, horror, monster-hunt, and long-campaign GMs have clearer recurring value than a generic player audience; players are the users and beneficiaries, but the GM controls module purchase and campaign policy.','project','created_document','provisional','SRC-MONSTER-GUIDE-44','buyer,gm,mystery,horror,monster-hunt'),
('F-155','monetization',NULL,'No observed price evidence yet supports Monster Field Guide','The checked sources prove demand signals and category implementations but do not prove a D&D5e GM will pay. A live choice among $5, $10, $15, $20, and no purchase plus a scheduled pilot is required.','project','created_document','provisional','SRC-MONSTER-GUIDE-45','price,willingness-to-pay,buyer-validation'),
('F-156','licensing',NULL,'The rights-safe product boundary is customer-owned data','The first version should read installed actor data and GM-entered or user-provided notes, and should not distribute copied Monster Manual text, protected art, or an unlicensed lore library. Tool behavior is safer than republishing protected content.','global','static','provisional','SRC-MONSTER-GUIDE-45','licensing,user-owned-data,statblocks,lore,rights'),
('F-157','portability',NULL,'Cross-VTT portability belongs at the neutral knowledge-packet layer','A portable packet can represent creature identity, player, evidence event, reveal tier, provenance, uncertainty, and capability requirements. Live actor reads, permissions, rolls, cards, and chat require separate Foundry, PF2e, Roll20, or other adapters.','project','created_document','provisional','SRC-MONSTER-GUIDE-45','cross-vtt,portability,packet,adapter'),
('F-158','technical',NULL,'Monster Field Guide needs a smaller exact disposable fixture','The target fixture should use synthetic actors and two users to test unknown-state projection, Study or equivalent check, GM approval, tiered reveal, per-player persistence, reconnect, duplicate suppression, permission denial, and authoritative read-back on Foundry 14.367 / D&D5e 5.3.3.','project','created_document','provisional','SRC-MONSTER-GUIDE-45','runtime,fixture,permissions,synthetic,foundry,dnd5e'),
('F-159','buyer-validation',NULL,'A silent visual demo and real price choice are the correct next market gate','Show an unknown creature becoming a tiered, player-safe field-guide entry in 20â€“30 seconds, then compare the GM''s actual workaround and ask for a one-time price and scheduled pilot. Player enthusiasm or survey-only interest is not payment evidence.','project','created_document','provisional','SRC-MONSTER-GUIDE-45','buyer-test,demo,price,pilot,marketability'),
('F-160','market-selection',NULL,'Monster Field Guide is a conditional lead, not an approved product','Advance only if qualified GMs recognize a recent incident, prefer the workflow over the real workaround, choose non-zero payment, schedule pilots, and the fixture protects hidden knowledge. Otherwise reject the candidate and reopen the fresh product search.','project','created_document','provisional','SRC-MONSTER-GUIDE-45','conditional,go-no-go,market-selection,research'),
('F-161','buyer-pain',NULL,'Players request simple item and currency exchange','A current Foundry wish-list discussion asks for a focused drag-offer/accept trade window and small chat receipt, which is a recurring usability complaint but not direct payment evidence.','project','static','provisional','SRC-LOGISTICS-MEMORY-46','trade,inventory,currency,player,demand'),
('F-162','competition',NULL,'Current Foundry trading substitutes already cover the obvious logistics job','Item Piles supports robust player trading, merchants, and loot; Give Items Between Players, Let''s Trade 5e, Shop, and RPGX Loot Crate cover focused, system-specific, or paid/free-tier variants.','project','static','provisional','SRC-LOGISTICS-MEMORY-46','trade,competition,item-piles,loot,shop'),
('F-163','buyer-pain',NULL,'Campaign knowledge and player-facing notes are recurring but crowded','Foundry journals/map notes, Campaign Codex, World & Campaign Builder, external LegendKeeper/Obsidian workflows, and Familiar already address linked lore, shared notes, search, and memory.','project','static','provisional','SRC-LOGISTICS-MEMORY-46','campaign-memory,codex,notes,wiki,competition'),
('F-164','market-selection',NULL,'Generic trade, treasury, campaign wiki, and AI memory should not be fresh wide-market products','These jobs recur, but their alternatives are mature, familiar, free, subscription-backed, or already paid. A new product would need a sharply differentiated outcome rather than another organizer or transfer dialog.','project','created_document','provisional','SRC-LOGISTICS-MEMORY-46','rejection,market-selection,trade,memory,treasury'),
('F-165','competition',NULL,'ANewFoe covers nearly the full baseline Monster Field Guide workflow','The current ANewFoe listing explicitly includes hidden unknown monsters, per-player known state, token-picture switching, basic-stat reveal, bulk upload, GM approval, and DC modifiers.','project','static','provisional','SRC-MONSTER-COMP-47','anewfoe,competition,baseline,monster-knowledge'),
('F-166','technical-gap',NULL,'ANewFoe leaves a possible modern-target maintenance gap but not a proven market gap','ANewFoe lists available release 1.0.3 as Foundry 12+ / Verified 12 with an old update trail, while the official D&D5e system has an actively maintained 6.0.x line. This supports a compatibility hypothesis only; it does not show that customers will migrate.','project','static','provisional','SRC-MONSTER-COMP-47','anewfoe,foundry-v12,dnd5e-v6,maintenance,unverified'),
('F-167','competition',NULL,'PF2E Bestiary Tracking demonstrates current selective-reveal value in another system','PF2E Bestiary Tracking is current on Foundry v14 and provides GM/player bestiary views with selective reveal, validating the category while showing that system adapters and data boundaries are real work.','project','static','provisional','SRC-MONSTER-COMP-47','pf2e,bestiary,reveal,adapter,competition'),
('F-168','product-gap',NULL,'The remaining Monster Field Guide wedge is evidence-to-knowledge, not bestiary storage','A candidate must connect Study or observed events to GM-approved tiered facts, per-player provenance, uncertainty, persistent codex entries, and an immediate player-facing visual change. A generic bestiary or statblock viewer is already occupied.','project','created_document','provisional','SRC-MONSTER-COMP-47','evidence,provenance,study,reveal,product-gap'),
('F-169','market-selection',NULL,'Monster Field Guide confidence was downgraded after direct competition re-audit','Keep it as the research lead only until a side-by-side ANewFoe/manual/Study comparison produces a real GM price choice and scheduled pilot. If modernization is its only advantage, reject it and reopen the search.','project','created_document','provisional','SRC-MONSTER-COMP-47','conditional,price,pilot,go-no-go,anewfoe'),
('F-170','runtime',NULL,'The exact disposable Foundry target starts and reaches the native setup/join surface','The package-only dbx-test-world fixture passed explicit data-path, world, process, port, version, and HTTP-readiness checks for Foundry 14.367 / D&D5e 5.3.3.','project','deterministic','active','SRC-RUNTIME-MONSTER-48','runtime,foundry,dnd5e,fixture,startup'),
('F-171','runtime',NULL,'Per-user hidden-state behavior remains blocked by missing synthetic users','The fixture join page had zero users and free-text credentials; the native setup/admin surface was reachable, but creating the synthetic GM/Player3 accounts was a separate native user-management operation and was not bypassed.','project','created_document','blocked','SRC-RUNTIME-MONSTER-48','runtime,users,permissions,hidden-state,blocked'),
('F-172','safety',NULL,'The exact runtime probe preserved the campaign-data boundary','The probe used only the isolated fixture, recorded zero world-document writes and no Ballad access, dismissed the optional usage-data prompt without enabling sharing, and stopped with no listener on port 30002.','project','deterministic','active','SRC-RUNTIME-MONSTER-48','fixture,no-write,campaign-boundary,stopped'),
('F-173','technical-product-boundary',NULL,'Monster Field Guide exact runtime evidence is partial, not a readiness claim','Startup and setup UI are proven, but per-user projection, GM approval, Study/equivalent action, persistence, reconnect, duplicate suppression, and hidden-state protection remain untested.','project','created_document','blocked','SRC-RUNTIME-MONSTER-48','monster-field-guide,runtime,permissions,not-ready');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,tags) VALUES
('F-174','buyer-pain',NULL,'Foundry users repeatedly need world cleanup and preflight diagnosis','Current community requests and defect reports describe duplicate actors/assets, empty or unconfigured documents, broken UUID/file paths, orphaned token references, and invalid data that can surface after migration or package changes. This establishes recurring operational pain but not payment.','project','static','provisional','SRC-WORLD-DOCTOR-49','world-health,cleanup,broken-links,duplicates,upgrade,gm'),
('F-175','competition',NULL,'Foundry and current tools cover pieces of world safety but not one evidence-linked preflight','Foundry provides backup, package compatibility, and migration guidance; Sephral''s Content Backup & Restore handles named document recovery; Lore Reference Board repairs links in its own import/export surface; fvtt-world-tools handles file-oriented cleanup; Dedupe This! is stale. No checked source establishes a current whole-world diagnosis-and-repair product.','project','static','provisional','SRC-WORLD-DOCTOR-49','competition,backup,migration,repair,world-audit'),
('F-176','product-gap',NULL,'The World Doctor wedge is diagnosis plus reversible repair, not backup or deduplication','A differentiated product would scan a world and its dependencies, show the affected object and evidence path, preview a narrow repair, snapshot before writing, reread the authoritative result, and produce an undo receipt. A backup, red/amber/green compatibility badge, or duplicate finder alone is insufficient.','project','created_document','provisional','SRC-WORLD-DOCTOR-49','world-doctor,preflight,diagnosis,repair,receipt'),
('F-177','buyer',NULL,'The likely payer for World Doctor is the GM or host with expensive campaign state','The buyer controls the world, module stack, backups, and upgrade decision; players benefit indirectly from fewer broken sessions. The strongest cohort is a GM with a long-running/import-heavy world or a recent upgrade/data incident, not an arbitrary player.','project','created_document','provisional','SRC-WORLD-DOCTOR-49','buyer,gm,host,campaign,incident'),
('F-178','marketing',NULL,'The eye-catching World Doctor promise is safe-to-update confidence','The front door should show â€œIs my world safe to update tonight?â€ with an evidence-linked defect, repair preview, and verified result. â€œDatabase cleanupâ€ or â€œcompatibility dashboardâ€ would make the value invisible or interchangeable.','project','created_document','provisional','SRC-WORLD-DOCTOR-49','marketing,eye-catching,safe-update,preflight'),
('F-179','portability',NULL,'World Doctor can share a neutral health report but not a universal live repair engine','A portable report can represent document references, asset paths, dependency edges, severity, confidence, suggested repair, and recovery receipts. Foundry document APIs, backups, permissions, and migration behavior require a separate adapter for every other VTT.','project','created_document','provisional','SRC-WORLD-DOCTOR-49','cross-vtt,portability,report,adapter'),
('F-180','market-selection',NULL,'World Doctor is a conditional fresh candidate, not a selected product','Advance only if qualified GMs with recent incidents prefer the evidence-linked diagnosis and reversible repair, choose a non-zero price, schedule a pilot, and the exact fixture proves no false green, hidden write, or unrecoverable repair. Otherwise reopen the search.','project','created_document','provisional','SRC-WORLD-DOCTOR-49','conditional,price,pilot,go-no-go');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,tags) VALUES
('F-181','buyer-pain',NULL,'Foundry upgrade incidents create real but directional GM cost','Community reports describe system or module updates breaking sheets, modules, or campaign behavior; users respond with archived worlds, backups, manual repair, or stopping updates mid-campaign. This supports recurring pain but does not establish current market size or payment.','project','static','provisional','SRC-WORLD-DOCTOR-50','world-health,upgrade,incident,gm,pain'),
('F-182','competition',NULL,'Backup and support already cover the obvious recovery job','Foundry provides built-in backups, package backups, snapshots, and rollback, while hosting/support guidance directs users toward compatibility diagnosis, disabling modules, downgrading, and restoring an export. A backup manager is therefore not a fresh product wedge.','project','static','provisional','SRC-WORLD-DOCTOR-50','competition,backup,snapshot,rollback,forge'),
('F-183','product-gap',NULL,'The remaining wedge is preflight diagnosis plus reversible repair','A potential product gap remains between a package snapshot and a healthy playable world: evidence-linked diagnosis of asset paths, behavioral/module interactions, malformed shapes, and orphaned references, followed by a previewed, narrow, verifiable, reversible repair.','project','created_document','provisional','SRC-WORLD-DOCTOR-50','world-doctor,preflight,diagnosis,repair,assets,compatibility'),
('F-184','monetization',NULL,'Directional pricing evidence favors buy-once or flat support testing','A current community pricing discussion reports fatigue with roughly $7â€“10/month creator subscriptions and preference for buy-once or flat support, while also showing that Foundry users do pay for modules/content. This is directional category evidence, not World Doctor willingness to pay.','project','static','provisional','SRC-WORLD-DOCTOR-50','pricing,buy-once,subscription,foundry-users'),
('F-185','price-test',NULL,'Initial World Doctor price anchors are $15, $25, and $39 one-time','Use $15, $25, and $39 as initial buyer-choice anchors for a one-time GM/host utility. These are research design choices; a price is evidence only when a qualified buyer chooses it and accepts a disposable-copy pilot.','project','created_document','provisional','SRC-WORLD-DOCTOR-50','price-test,one-time,gm,host,pilot'),
('F-186','market-selection',NULL,'World Doctor remains conditional and must not become a backup manager','Keep the candidate only if qualified GMs prefer evidence-linked preflight and reversible repair over their real workaround, choose a non-zero price, and complete a safe fixture/pilot. Reject a prettier backup, generic compatibility dashboard, duplicate finder, or warning list that leaves diagnosis to the buyer.','project','created_document','provisional','SRC-WORLD-DOCTOR-50','conditional,go-no-go,backup,research-gate');

INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-001','product','Name the central project DiceBox Campaign Helper and use it for the program plus associated Foundry VTT module.','Provides one stable project identity while preserving the previous Campaign Assistant research as foundation.','project','locked','project','SRC-COMPILE',NULL),
('D-002','module-boundary','Expose a small semantic public API: describe, supports, execute, query, resolve, health.','Prevents arbitrary Foundry mutation and gives the module a stable bridge contract.','global','locked','bridge','SRC-FOUNDATION',NULL),
('D-003','compiler-order','Compile D&D5e mechanics Activity-first, then Midi composition, then Effects/DAE, Region/Scene, Additional Activity, and macro only as last resort.','Uses native system semantics and avoids giant procedural macros.','global','locked','compiler','SRC-CHAT-AITRAP',NULL),
('D-004','runtime-authority','Treat the active GM as authoritative executor for protected player-triggered world mutations.','Foundry permissions reject direct player updates and active-GM routing prevents duplicate writers.','global','locked','runtime','SRC-REGION-DOSSIER',NULL),
('D-005','spatial','Freeze Spatial Blueprint before map art or Foundry placeable compilation.','Avoids geometry drift, misaligned grids, invented doors, and image-first topology errors.','global','locked','spatial','SRC-FOUNDATION',NULL),
('D-006','database','Use SQLite with normalized tables plus FTS5 search for the central KB.','Keeps provenance, facts, trials, open work, research, and milestones queryable without requiring an external service.','project','locked','knowledge','SRC-COMPILE',NULL),
('D-007','evidence','Mark capabilities unavailable or unverified when exact runtime proof is missing; fail closed or use a verified fallback.','Prevents source/test/chat success from becoming false live certification.','global','locked','validation','SRC-FOUNDATION',NULL),
('D-008','campaign-scope','Keep campaign packs separate from global module contracts.','Prevents Iggwilv/Prime Arachnid content and authored UUIDs from becoming hidden global assumptions.','global','locked','content','SRC-AUDIT',NULL),
('D-009','packaging','Create the dicebox-campaign-helper Foundry package and manifest during M2, even while the first runtime is read-only.','A valid package boundary is required for clean load, compatibility checks, and later updates.','project','locked','module','SRC-GAP-RESEARCH',NULL),
('D-010','transactions','Use modifyBatch only for independent operations; use staged journaled transactions for dependent IDs and cross-document links.','Matches Foundry v14 batch semantics and preserves recovery information.','global','locked','runtime','SRC-GAP-RESEARCH',NULL),
('D-011','knowledge','Treat the SQLite KB as a compiled read-only index until edit synchronization, migrations, and FTS triggers are implemented.','Avoids stale or inconsistent search results while retaining a reproducible local build.','project','locked','knowledge','SRC-GAP-RESEARCH',NULL),
('D-012','market-product-direction','Use Campaign Continuity / Campaign Safe Mode as the provisional first-product thesis; keep Player Turn Coach as a later feature or bundle.','The competitor pass shows action access, reminders, tracking, timing, planning, memory, and AI continuation are already served by adjacent products. A typed, inspectable, selectively mergeable session branch offers a narrower GM-paid outcome and stronger reuse of DiceBox safety/provenance assets.','project','proposed','product-research','SRC-CONTINUITY-PASS',NULL),
('D-013','market-portability','Treat cross-VTT support as a neutral session-packet boundary, not a universal live-sync promise.','Player-facing companion features are crowded and platform APIs differ. A portable packet can widen the market without pretending Roll20, Fantasy Grounds, and Foundry share one mutation model.','project','proposed','product-research','SRC-PLAYER-PASS',NULL),
('D-014','market-positioning','Use Campaign Continuity as the public product name and Campaign Safe Mode as the internal feature name.','The public promise is a visible continuity outcomeâ€”continue after disruption, compare the branch, keep or discardâ€”while Safe Mode sounds like invisible infrastructure. The rename remains provisional until message testing.','project','proposed','product-research','SRC-MARKETING-PASS',NULL),
('D-015','market-productization','Use the Canon & Branch Board as the provisional public hero surface, not as a separate campaign wiki.','The current Foundry premium catalog rewards immediate visual outcomes. A branch-backed timeline and semantic diff can create a glanceable demo while preserving the real value: recovery effort, hidden-state protection, and selective canonization.','project','proposed','product-research','SRC-HERO-ARTIFACT-PASS',NULL),
('D-016','market-product-selection','Run Campaign Continuity and Campaign Guardian as separate head-to-head offers before combining or selecting one.','Continuity has a differentiated branch/merge concept but mixed urgency; Guardian has stronger game-night fear but competes with free backup workflows. A direct recent-pain and purchase-choice comparison is the next valid selection step.','project','proposed','product-research','SRC-URGENCY-PASS',NULL),
('D-017','market-product-selection','Reject Campaign Guardian, generic Campaign Replay, and generic improvisation as standalone first products; retain their useful behaviors as features or alternatives.','Current Foundry, Forge, Battle Replay, Encounter Forge, RPGM Forge, Escalating Encounters, and Perceived Reality cover the broad promises. Continue testing only the narrower semantic non-combat branch/merge outcome.','project','proposed','product-research','SRC-REJECTION-23',NULL),
('D-018','technical-product-boundary','Prototype Campaign Continuity as a read-only/preview-first Foundry branch with staged GM-authorized merge; do not claim atomic rollback or universal state coverage.','Official v14 API primitives support serialization, ephemeral clones, validation, permission checks, and document operations, but cross-document transaction and module-owned-state limits require explicit recovery and unsupported-state boundaries.','project','proposed','runtime','SRC-TECH-PASS',NULL),
('D-019','market-product-selection','Reject Campaign Continuity / Campaign Safe Mode as the first storefront product; retain its branch, provenance, visibility, reset, and recovery mechanics as reusable infrastructure.','The five-second promise remains weak, the problem is episodic, and current backups, notes, duplicate worlds, dashboards, and continuity tools provide credible alternatives. A polished board does not yet prove a paid outcome.','project','proposed','product-research','SRC-ATTENTION-PASS',NULL),
('D-020','market-product-selection','Open the next candidate as Adventure Capsules: short, ready-to-run, player-visible premium sessions with reusable continuity/reset support.','A finished evening with visible scenes, reveals, handouts, and choices is more glanceable and repeat-purchasable than invisible campaign safety, but premium adventures and map packs are direct competitors and buyer choice is untested.','project','proposed','product-research','SRC-ATTENTION-PASS',NULL),
('D-021','market-product-selection','Reject generic Adventure Capsules and narrow the candidate to Adaptive Drop-In Capsules for variable attendance and no-canon side sessions.','Current premium adventures already provide ready-to-run content and visual polish. The only untested wedge with a clearer recurring job is a rapid, bounded side session that preserves the main campaign when attendance changes.','project','proposed','product-research','SRC-ADVENTURE-PASS',NULL),
('D-022','technical-evidence-boundary','Run the next Foundry test only in a bounded disposable fixture and keep the manifest preflight separate from live readiness.','The exact target stack is locally available, but no live ready-hook, authority, document, failure-recovery, or read-back evidence exists. Existing campaign worlds must remain untouched.','project','proposed','runtime','SRC-RUNTIME-AVAILABILITY',NULL),
('D-023','market-product-selection','Keep Campaign Continuity / Safe Mode out of the storefront and test Game Night Rescue as the provisional productized form of Adaptive Drop-In Capsules.','The new message is visually and emotionally clearer, but its paid unit must be a finished no-canon capsule plus attendance and safe-exit workflow. No implementation or product selection is authorized until recent buyer pain and real purchase choice are observed.','project','proposed','product-research','SRC-EYE-CATCHING-28',NULL),
('D-024','market-positioning','Market the candidate with a trigger-to-payoff demonstration and trust proof.','A five-second â€œplayer absent â†’ game continuesâ€ sequence, first-minute playable proof, exact compatibility, no-canon boundary, rights disclosure, and reviews are more legible than safety or branch terminology. This is a test plan, not evidence of conversion.','project','proposed','product-research','SRC-EYE-CATCHING-28',NULL),
('D-025','market-product-selection','Test Game Night Rescue first with paid/professional GMs and high-variance organizers, not as a broad home-game product.','Home tables often have low-cost social workarounds, while paid and organized hosts have measurable prep, booking, and retention value. If that payer cohort does not choose the product at a real price, reject the candidate and reopen the search.','project','proposed','product-research','SRC-PAYER-SEGMENT-29',NULL),
('D-026','market-product-selection','Retain DMF as a serious competing candidate, but test it as Custom Item Workshop rather than as a generic AI item creator or raw Midi-QOL script generator.','The local project has a credible end-to-end automation gap, while plain item generation has direct competition and simple items have cheap alternatives. Product selection requires buyer evidence from ordinary and automation-heavy GMs.','project','proposed','product-research','SRC-DMF-MARKET-30',NULL),
('D-027','product-architecture','Retain DMF compiler, review, capability, provenance, and verification assets regardless of which storefront candidate wins.','These assets can support Game Night Rescue or a future cross-VTT recipe compiler, but technical reuse must not be treated as proof that DMF itself is marketable.','project','proposed','product-research','SRC-DMF-MARKET-30',NULL),
('D-028','market-positioning','Position DMF as the automation completion layer beyond Automaker, not as a faster basic item generator.','Automaker establishes a strong speed/direct-insertion baseline. DMF should win only when a custom item needs cross-module wiring, dependency explanation, repair, and verification.','project','proposed','product-research','SRC-AUTOMAKER-COMPARE-31',NULL),
('D-029','product-architecture','Make DMF Foundry-first with a portable neutral recipe/receipt boundary and separate future VTT adapters.','Foundry Activities, Midi-QOL, DAE, and Item Macro are not shared runtime contracts with Roll20 or Fantasy Grounds. Portability is honest at the intent/evidence layer; live automation needs distinct projections and verification.','project','proposed','product-research','SRC-DMF-PORTABILITY-32',NULL),
('D-031','market-product-selection','Open Foundry Upgrade Guardian as the leading fresh product hypothesis and keep DMF backburnered as an internal compiler asset.','Upgrade breakage is recurring, broad, visible, and connected to paid modules and active campaigns. Existing backups and compatibility tools create a clear but unproven gap for world-specific disposable rehearsal and smoke-test receipts.','project','proposed','product-research','SRC-UPGRADE-GUARDIAN-34',NULL),
('D-032','product-architecture','Implement Upgrade Guardian first as a local setup companion with an optional Foundry probe, not as a self-modifying in-world module.','The active world cannot safely replace its own runtime or rehearse a future stack in place. A closed-world companion workflow preserves the live campaign and supports explicit evidence labels, while avoiding redistribution of Foundry or premium content.','project','proposed','product-research','SRC-UPGRADE-TECH-35',NULL),
('D-033','market-product-selection','Do not select generic Upgrade Guardian; retain Campaign Runtime Locker as a conditional self-hosted hypothesis.','Foundry already supplies pre-update compatibility checks, backups, portable builds, and multi-version guidance, while hosting services sell version switching and snapshots. The remaining wedge is per-world known-good runtime locking and one-click local launch, which must beat manual installs and hosting in a real price test.','project','proposed','product-research','SRC-RUNTIME-LOCKER-36',NULL),
('D-034','market-product-selection','Reject a generic performance monitor; retain Session Health Autopsy as a conditional new-product hypothesis.','Current modules already monitor performance, optimize rendering, adjust per-player profiles, and bisect modules. The only plausible wedge found is an eye-catching guided incident workflow that correlates affected clients with scene/assets/module events and produces a reversible action plan. It must earn a real GM price choice before implementation.','project','proposed','product-research','SRC-SESSION-HEALTH-37',NULL),
('D-035','market-product-selection','Reject a generic mobile companion; keep a low-bandwidth browser relay as a secondary conditional hypothesis.','Foundry''s core gap is real and Roll20''s browser investment validates demand, but current Foundry products already cover mobile sheets, touch controls, maps, chat, combat, and invite-based companions. A relay is worth testing only if it reaches weaker devices with less setup and lower resource use than those alternatives.','project','proposed','product-research','SRC-MOBILE-RELAY-38',NULL),
('D-036','market-product-selection','Advance Thin Client Player Relay as the leading conditional buyer hypothesis, not as a full mobile companion.','The payer pass found explicit â‚¬15â€“â‚¬25 price anchors and a current â‚¬15 lifetime competitor, while full mobile companion capabilities are already occupied. The next test should target the unverified thin-client wedge: no app installation, low bandwidth, weak-device reach, and a Foundry-authoritative action gateway.','project','proposed','product-research','SRC-PAYER-MOBILE-39',NULL),
('D-037','technical-product-boundary','Pass the static technical and licensing screen for a Foundry-first thin client, but do not certify the product yet.','Official module sockets, public APIs, connected clients, role/document permissions, and licensing guidance support a narrow module-mediated relay. They do not prove external browser authentication, reconnect behavior, weak-device performance, full Activity/Midi-QOL fidelity, or cross-VTT live execution. Reject any design that requires a cloud control plane, direct player document writes, private API guarantees, or bundled protected content; advance only to an exact disposable read-only/typed-request fixture.','project','proposed','runtime','SRC-THINCLIENT-TECH-40',NULL),
('D-038','market-product-selection','Retain Player Flow / Tabletop Ease Mode as an alternate conditional hypothesis; reject generic HUD and generic accessibility as standalone products.','Community evidence shows recurring player confusion and choice overload, while Foundry Navigator, Accessibility Enhancements, Stylish Action HUD, and party-inventory tools already cover slices of the problem. The only plausible new wedge is a per-player, task-driven cockpit that removes choices and reduces GM interruptions across systems. It must beat existing HUDs and simple onboarding in a direct task and price test before implementation.','project','proposed','product-research','SRC-PLAYER-FLOW-41',NULL),
('D-039','market-product-selection','Reject Player Flow / Tabletop Ease Mode as a standalone first product; retain its task-graph, guidance, and accessibility components for the Thin Client Player Relay or a bundled content product.','Foundry already provides player tutorials and a knowledge base, while communities solve the problem with training sessions, mini-campaigns, screen sharing, existing HUDs, or simpler VTTs. A paid Beginner Box shows that onboarding can support a valuable content bundle, but no direct price evidence supports a generic cockpit. Reopen only if a future buyer test produces actual GM payment or pilot commitment.','project','proposed','product-research','SRC-PLAYER-FLOW-42',NULL),
('D-040','market-product-selection','Reject generic drawing and collaborative whiteboard as a standalone first product; retain geometry/export auditing as a reusable component.','Recent users report drawing pain, but native Foundry, active drawing/wall modules, Owlbear, Miro, and paid MapForge occupy the obvious product surface. The narrower geometry audit is more creator-facing than the requested wide buyer market.','project','proposed','product-research','SRC-DRAWING-43',NULL),
('D-041','market-product-selection','Advance Monster Field Guide / Creature Codex as the fresh leading conditional product hypothesis.','The 2024 Study action supplies an ordinary D&D5e hook; ANewFoe proves the category; PF2E Bestiary Tracking shows current selective-reveal value; and a tiered evidence-backed codex has a more visible payoff than Safe Mode or another HUD. Payment and exact runtime evidence remain absent.','project','proposed','product-research','SRC-MONSTER-GUIDE-44',NULL),
('D-042','market-product-boundary','Do not implement Monster Field Guide until the qualified-GM, rights, portability, and exact disposable-runtime gates pass.','The payer is a GM with recurring knowledge-heavy play, while the rights-safe boundary is user-owned actor data and GM-entered notes. A neutral knowledge packet is portable, but live permissions and checks are platform-specific. Reject if the buyer sees bookkeeping, chooses no price, or hidden-state protection fails.','project','proposed','product-research','SRC-MONSTER-GUIDE-45',NULL),
('D-043','market-product-selection','Reject generic trade, treasury, campaign wiki, and campaign-memory products as fresh wide-market candidates.','Item Piles, focused trade modules, RPGX Loot Crate, Campaign Codex, World & Campaign Builder, Familiar, and external note systems already cover the broad jobs. Preserve transaction receipts, permissions, relationships, and notes as reusable assets.','project','proposed','product-research','SRC-LOGISTICS-MEMORY-46',NULL),
('D-044','market-product-boundary','Keep Monster Field Guide only as a downgraded conditional lead: modern D&D5e evidence-to-knowledge layer, not a generic bestiary.','ANewFoe covers almost all baseline behavior, PF2E Bestiary Tracking validates the category, and current campaign-memory products reduce the value of a broad codex. The only plausible wedge is evidence/provenance/Study integration with a visible table payoff, subject to real GM payment and pilot evidence.','project','proposed','product-research','SRC-MONSTER-COMP-47',NULL),
('D-045','technical-product-boundary','Do not promote Monster Field Guide to implementation after the startup-only fixture pass.','The exact disposable target is available and safe, but the fixture lacks synthetic users and therefore cannot yet prove per-player hidden-state projection or authority. Complete one native user-management setup and two-client read/permission test before any product build or readiness claim.','project','proposed','runtime','SRC-RUNTIME-MONSTER-48',NULL);

INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-046','market-product-selection','Promote World Doctor / Campaign Health to the newest conditional fresh-search candidate; keep Thin Client Player Relay open and Dungeon Master''s Forge backburnered.','World Doctor addresses a recurring GM/host costâ€”finding what will break in a complex world before an update or game nightâ€”and has a clearer paid trigger than generic player logistics. Foundry backup/migration, link repair, file cleanup, and document recovery tools occupy parts of the space, so diagnosis plus evidence-linked reversible repair must win a direct buyer trial.','project','proposed','product-research','SRC-WORLD-DOCTOR-49',NULL),
('D-047','market-product-boundary','Do not implement World Doctor until a synthetic-defect fixture and real GM price/pilot test pass.','The category can collapse into a prettier backup, generic warning dashboard, or stale dedupe tool. Require snapshot/preview/repair/reread/rollback evidence, a no-write campaign boundary, and qualified GMs choosing a non-zero price over their current workaround.','project','proposed','product-research','SRC-WORLD-DOCTOR-49',NULL);

INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-048','market-product-selection','Test World Doctor as a one-time GM/host utility with no subscription assumption.','Upgrade breakage creates a credible GM pain signal, but Foundry backup/snapshot and hosting support cover recovery. Test only the narrower preflight diagnosis plus evidence-linked reversible repair at $15, $25, and $39 one-time anchors.','project','proposed','product-research','SRC-WORLD-DOCTOR-50',NULL),
('D-049','market-product-boundary','Reject World Doctor if backup, support, or generic compatibility warnings are good enough.','The product must name the affected object, show evidence, preview a narrow repair, verify the authoritative result, and provide recovery. A warning list or duplicate finder leaves the hard diagnostic work with the GM and is not a defensible paid product.','project','proposed','product-research','SRC-WORLD-DOCTOR-50',NULL);

INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-001','implementation','Create DiceBox repository/module skeleton','No DiceBox-specific repository or module package exists yet.','Review the completed M0 contract spine before beginning M1 runtime probing.','Static typecheck/tests, no-op module load, and explicit absence of mutation surface; live Foundry proof remains pending.','P0','closed','core','SRC-M0-IMPLEMENTATION'),
('O-002','implementation','Implement queryable KB service','Narrative files are not sufficient for retrieval during compiler work.','Build SQLite schema, seed data, FTS5 indexes, query examples, and provenance views.','Database integrity, FTS queries, source coverage report.','P0','in_progress','knowledge','SRC-COMPILE'),
('O-003','certification','Exact Foundry 14.367 runtime probe','DMF and Regionwright evidence is mostly on older 14.365-era targets.','Run capability, event, User.query, DataModel, Scene/Region/Activity probes on exact target.','Runtime fingerprint and probe receipts.','P0','open','runtime','SRC-AUDIT'),
('O-004','defect','DMF Region Builder settings-open defect','Undeclared items variable causes the settings path to fail.','Fix explicit item collection dependency and add smoke test, or exclude builder from first DiceBox slice.','Deterministic test and live settings-open proof.','P1','open','dmf-adapter','SRC-DMF-DOSSIER'),
('O-005','reconciliation','Unify Region plan schema','Design documents describe schema 2.0 while implementation/tests expose 1.0.','Select canonical schema, write migration, and reject ambiguous versions.','Schema migration and round-trip tests.','P1','open','region-adapter','SRC-AUDIT'),
('O-006','certification','Fresh two-client authority test','Live Player3 success/denial/reconnect evidence remains incomplete.','Test player request, active-GM execution, timeout, reconnect, duplicate suppression, and read-back.','GM/player evidence receipts on exact target.','P0','open','runtime','SRC-REGION-DOSSIER'),
('O-007','implementation','StateStore persistence prototype','Campaign truth/runtime state storage driver is not physically selected or benchmarked.','Compare module settings, world flags, journal-backed state, and external storage; choose scoped authoritative driver.','Restart, migration, concurrency, and corruption recovery tests.','P1','open','state','SRC-CHAT-RESEARCH5'),
('O-008','implementation','Transaction ledger prototype','Foundry operations may require staged creation, unknown commit recovery, and compensating rollback.','Implement journaled idempotent staged transaction fixture with authoritative reread.','Failure injection and repair receipts.','P1','open','runtime','SRC-CHAT-MACRO'),
('O-009','implementation','Activity/Midi capability registry','Registered classes and settings descriptions can diverge; optional modules are version-sensitive.','Inspect actual dnd5e Activity classes, Midi registration, DAE lifecycle, and installed manifests.','Capability snapshot on exact stack plus unavailable fallbacks.','P0','open','automation','SRC-CHAT-AITRAP'),
('O-010','research','Targeted early-subject deepening','The #1-#20 retrofit is complete but broad rather than equally deep.','Deepen Actors/Items, Scenes-Walls, Regions/Behaviors/Levels, and Lights/Tiles only where implementation risk requires.','Current official/source/community evidence and regression additions.','P2','open','research','SRC-CHAT-RESEARCH'),
('O-011','certification','Clean-world install and recovery','No full cold bootstrap, backup, restore, and selective repair proof exists.','Build disposable exact-stack world, install frozen bundle, restart, back up, restore, and repair one component.','Patch-free recovery receipts.','P1','open','release','SRC-COMPILE'),
('O-012','implementation','Performance benchmark','Campaign-scale Actors, Items, Regions, assets, and placeables are not benchmarked.','Benchmark representative small/medium/large campaign fixtures and player clients.','Measured budgets and degradation policy.','P2','open','performance','SRC-CHAT-RESEARCH'),
('O-013','reconciliation','Retarget DMF/Regionwright evidence to 14.367','Current project verification fingerprints are older than the DiceBox target.','Run exact-stack compatibility and live probes before adapter promotion.','Versioned evidence ledger.','P0','open','validation','SRC-AUDIT'),
('O-014','certification','Regionwright teleport promotion','Teleport landing, permissions, bounce, rollback, and reset lack live proof.','Keep deferred; implement isolated two-scene fixture only after capability and loop guards pass.','Full-function live evidence and reset proof.','P2','blocked','region-adapter','SRC-REGION-DOSSIER'),
('O-015','implementation','KB live-edit synchronization','FTS5 indexes are built deterministically but not synchronized for arbitrary live edits.','Add migrations, source-table triggers, rebuild command, and consistency tests before enabling editing.','Index/source consistency after insert/update/delete and migration.','P2','open','knowledge','SRC-GAP-RESEARCH'),
('O-016','release','Module manifest and update workflow','Foundry package metadata, download, update, and exact compatibility are not yet implemented for DiceBox.','Create manifest, package build, clean install/update test, and immutable artifact fingerprint.','Clean install/update/rollback evidence.','P1','open','module','SRC-GAP-RESEARCH'),
('O-017','research','Validate Campaign Safe Mode buyer pain and willingness to pay','The current finalist is supported by market and competitor evidence but no direct buyer or behavioral evidence.','Interview and prototype-test ten qualified Foundry D&D5e GMs using the buyer validation protocol before implementing product-specific behavior.','Recent disruption evidence, recovery-time comparison, purchase choice, trust, and no-go findings.','P0','open','product-research','SRC-BUYER-VALIDATION'),
('O-018','implementation','Prove semantic branch feasibility on exact Foundry stack','Foundry backups and document APIs do not by themselves prove safe selective branch/merge across actor, item, scene, journal, combat, and module-owned state.','Build a disposable read-only/preview fixture for checkpoint, branch, diff, selective merge, discard, retry, and read-back on the exact target stack.','Exact runtime capability matrix, failure injection, permission/ownership proof, and recovery receipts.','P1','open','runtime','SRC-PORTABILITY-PASS'),
('O-019','research','Validate neutral session packet with players and cross-VTT buyers','Player-facing companion pain is real but current mobile, navigation, inventory, and accessibility tools are crowded.','Prototype a player-safe re-entry packet and test it with Foundry GMs, players, paid campaign organizers, and one non-Foundry workflow before implementing a second live adapter.','GM purchase choice, player comprehension, hidden-state protection, packet usefulness outside Foundry, and no-go findings.','P1','open','product-research','SRC-PLAYER-PASS'),
('O-020','research','Validate Campaign Continuity attention and desirability','Safe Mode may be valuable only after explanation and may not win marketplace attention.','Run five-second, thirty-second, alternative, message, and trust tests with qualified GMs before building marketing assets or changing the product scope.','Unaided comprehension, install intent, alternative preference, purchase choice, trust objections, and no-go findings.','P0','open','product-research','SRC-MARKETING-PASS'),
('O-021','research','Validate Canon & Branch Board as a hero artifact','A polished timeline could become a pretty recap and fail to improve recovery or protect hidden state.','Show the Board without technical explanation and compare it with backup, journal, duplicate-world, and ordinary recap workflows.','Unaided comprehension, click intent, player-safe usefulness, recovery-time reduction, trust, willingness to pay, and no-go findings.','P0','open','product-research','SRC-HERO-ARTIFACT-PASS'),
('O-022','research','Run Campaign Continuity versus Campaign Guardian buyer test','Continuity may be an elegant but episodic edge case, while Guardian may be a more urgent but crowded backup category.','Show both narrow 30-second offers to qualified GMs and record recent pain, workaround, lost value, install intent, purchase choice, and rejection reason.','Head-to-head buyer evidence with actual recent incidents and one-time purchase choice.','P0','open','product-research','SRC-URGENCY-PASS'),
('O-023','research','Validate the narrowed semantic branch/merge gap against direct alternatives','Current visual and backup surfaces are covered by adjacent products; only semantic non-combat selective canonization remains provisional.','Test a branch across actors, items, scenes, journals, objectives, and hidden state against backup, replay, notes, one-shot, and manual duplicate-world workflows.','Recent buyer incident, recovery-time comparison, hidden-state correctness, selective merge comprehension, willingness to pay, and no-go findings.','P0','open','product-research','SRC-REJECTION-23'),
('O-024','implementation','Build exact Foundry branch feasibility fixture','M0 is static/deterministic only; API documentation does not prove an exact-world multi-document branch and merge.','On Foundry 14.367 / D&D5e 5.3.3, capture source data, create an ephemeral branch, validate changes, filter player/GM visibility, stage a GM merge, inject a failure, reread, and recover.','Versioned runtime receipts for Actors, Items, Scenes, Journals, objectives, permissions, failure recovery, and unsupported module-owned state.','P0','open','runtime','SRC-TECH-PASS'),
('O-025','research','Run the eye-catching buyer-choice gate','Campaign Continuity may be useful but not desirable at first glance, while Adventure Capsules may look better without proving repeat purchase or buyer value.','Run five-second, thirty-second, alternative, trust, and actual price-choice tests for both offers with qualified GMs.','Unaided comprehension, install intent, selected price, actual commitment, scheduled run, repeat intent, and rejection reason.','P0','open','product-research','SRC-ATTENTION-PASS'),
('O-026','research','Research Adventure Capsules competition, rights, and portability','Ready-to-run premium adventures and content packs are visually compelling but may be crowded, licensed, system-specific, or labor-intensive.','Map current premium adventures, cinematic content, map packs, and one-shot workflows; compare prices, update promises, rights, and neutral exports before selecting a format.','Direct competitor feature/pricing matrix, licensing boundary, prep-time delta, and buyer-choice result.','P0','open','product-research','SRC-ATTENTION-PASS'),
('O-027','research','Validate the Adaptive Drop-In Capsule attendance wedge','The narrowed candidate may solve a real recurring scheduling problem, but groups may prefer cancellation, ghosting, second worlds, free PDFs, or existing adventures.','Interview and prototype-test qualified GMs using a recent absence incident, then run the no-canon capsule against the selected alternative.','Recent incident frequency, prep-time delta, no-canon comprehension, scheduled run, repeat intent, and actual price choice.','P0','open','product-research','SRC-ADVENTURE-PASS'),
('O-028','research','Define the Adaptive Drop-In rights and portability packet','System-specific rules, stat blocks, assets, audio, and Foundry automation can block cross-VTT distribution or create licensing debt.','Define an original/SRD-safe narrative packet, asset manifest, Foundry projection, and one read-only non-Foundry export before content production.','Rights matrix, attribution, asset provenance, export fixture, and compatibility boundary.','P1','open','product-research','SRC-ADVENTURE-PASS'),
('O-029','implementation','Execute the exact live Foundry readiness probe','Manifest evidence exists, but live runtime behavior is untested.','Run a bounded disposable fixture on Foundry 14.367 / D&D5e 5.3.3; observe ready hook, world/system/module identity, active GM authority, read-only party state, no-op/ephemeral branch behavior, and receipt/read-back.','Versioned live receipt with supported, unknown, blocked, and stop-at-first-unsafe classifications.','P0','open','runtime','SRC-RUNTIME-AVAILABILITY'),
('O-030','research','Run Game Night Rescue buyer-choice and message test','Campaign Continuity is rejected as a front-door promise, while the sharper attendance message is still only a hypothesis.','Show Safe Mode, Campaign Continuity, and Game Night Rescue cards plus the same silent workflow; compare against cancellation, free PDF, premium one-shot, and Omnipresence/second-world alternatives.','Unaided comprehension, named recent incident, selected price, scheduled run, alternative preference, no-canon trust, and rejection reason.','P0','open','product-research','SRC-EYE-CATCHING-28'),
('O-031','research','Create a no-code Game Night Rescue hero prototype','The candidate cannot be evaluated fairly through infrastructure screens or a generic adventure listing.','Build a static listing and short silent walkthrough showing present-player choice, no-canon state, one playable scene, and clean return without implementing Foundry mutation.','Five-second and thirty-second comprehension, first-minute task success, trust objections, and buyer-choice evidence.','P0','open','product-research','SRC-EYE-CATCHING-28'),
('O-032','research','Run the payer-specific Game Night Rescue pilot test','Home-GM reactions do not establish willingness to pay, and paid/rotating hosts have not yet been tested with an economic-value message.','Recruit paid/professional GMs, one West Marches or rotating organizer, and home GMs; quantify recent disruption cost, show the same workflow, compare alternatives, and record price or pilot commitment.','Recent financial/prep impact, buyer authority, named alternative, non-zero price, scheduled pilot, no-canon trust, and rejection reason.','P0','open','product-research','SRC-PAYER-SEGMENT-29'),
('O-033','research','Run the DMF / Custom Item Workshop buyer test','DMF has a stronger feature gap than plain item generators, but buyer demand may be limited to automation-heavy GMs or creators.','Recruit ordinary, automation-heavy, paid, and secondary creator cohorts; compare end-to-end compilation against native forms, Auto Maker, Item Creator, free macros, and community help.','Recent item incident, time saved, dependency trust, current workaround, non-zero price, real install/use, exact-stack proof, and neutral recipe export.','P0','open','product-research','SRC-DMF-MARKET-30'),
('O-034','research','Run a side-by-side DMF versus Automaker complex-item trial','Automaker establishes a fast baseline, but DMF''s claimed value is the behavior layer rather than the Item document.','Use the same complex custom item through native/Automaker, DMF core-only, and DMF verified-automation paths; measure setup and working behavior before testing price.','Time-to-working-item, module settings touched, manual edits, disposable-scene pass, warning comprehension, real price, and live-session use.','P0','open','product-research','SRC-AUTOMAKER-COMPARE-31'),
('O-035','research','Test the DMF neutral recipe and cross-VTT projection boundary','Foundry automation is not directly portable to Roll20 or Fantasy Grounds, and a broad claim would create hidden support and compatibility debt.','Export one complex item as a neutral recipe and receipt; compare Foundry output with an authoritative secondary-VTT projection only when supported, and label every loss or unavailable capability.','Transfer comprehension, manual rewrite, dropped behavior, support burden, price change, and whether Foundry automation remains the purchase reason.','P1','open','product-research','SRC-DMF-PORTABILITY-32'),
('O-036','research','Run the Foundry Upgrade Guardian buyer and rehearsal test','Upgrade pain is broad, but built-in backups, staying on an old version, and manual troubleshooting may remain sufficient.','Use a disposable world with a representative module stack; compare backup-only, metadata-only, loadout/settings tools, and the scan/clone/smoke-test/receipt workflow.','Recent upgrade decision, caught failures, false alarms, time to confidence, willingness to upgrade, non-zero price, and pilot commitment.','P0','open','product-research','SRC-UPGRADE-GUARDIAN-34'),
('O-037','implementation','Build a read-only local upgrade rehearsal fixture','A credible rehearsal needs a closed-world clone, candidate package stack, selected smoke tests, and explicit handling for external state and entitlements.','Define the Windows companion boundary and produce a disposable fixture that scans manifests, records a rollback point, launches a candidate instance, runs an optional probe, and emits evidence-labeled results without touching a live world.','No live-world mutation, exact version fingerprints, clone isolation, disk/entitlement failure handling, smoke-test receipts, and restore verification.','P0','open','product-research','SRC-UPGRADE-TECH-35'),
('O-038','research','Test Campaign Runtime Locker against hosting and manual version management','The broad Upgrade Guardian promise overlaps Foundry''s own compatibility/backup features and paid hosting services.','Use the same multi-module world to compare waiting, manual portable installs, hosted version switching/snapshots, and a local per-world lock-and-launch workflow.','Self-hosting status, number of worlds, setup/recovery time, confidence, disk cost, failure capture, one-time price choice, monthly alternative choice, and pilot commitment.','P0','open','product-research','SRC-RUNTIME-LOCKER-36'),
('O-039','research','Run a Session Health Autopsy buyer trial against existing performance tools','Lag is a real player-facing pain, but the current category already contains monitors, optimizers, render fixes, and module bisection.','Recruit GMs with a recent disrupted session and at least one affected client; compare their current workaround, Axon/Performance Optimizer/Find the Culprit where applicable, and a guided cross-client incident workflow using a disposable scene or read-only trace.','Affected-client count, minutes lost, diagnostic time, root-cause confidence, false leads, reversible remediation success, recurrence, pilot use, and a real non-zero price choice.','P0','open','product-research','SRC-SESSION-HEALTH-37'),
('O-040','research','Test low-bandwidth browser relay against current mobile companions','Mobile pain is real, but existing products already provide touch sheets, maps, chat, actions, and invite links.','Test the same group on a weak or unsupported client with Sheet Only, Swipe/Tabletop Helpers or PocketScroll where available, and a minimal browser relay that avoids full-canvas rendering.','Join success, first-action time, bandwidth/device resource use, feature comprehension, setup friction, recurrence, GM purchase choice, and cross-VTT demand.','P1','open','product-research','SRC-MOBILE-RELAY-38'),
('O-041','research','Run the Thin Client Player Relay device and price test','Self-reported price interest and a â‚¬15 competitor establish a price anchor, but a new relay may not improve on existing mobile companions.','Compare the group''s current workaround, VTT Companion/PocketScroll or another available companion, and a no-install thin client on a weak device; test one-time GM prices of â‚¬15, â‚¬20, and â‚¬25.','Join success, first useful action, battery/bandwidth use, setup time, automation fidelity, table distraction, repeat use, and actual price choice.','P0','open','product-research','SRC-PAYER-MOBILE-39'),
('O-042','implementation','Build an exact Foundry thin-client feasibility fixture','Static documentation supports a module socket and permission-aware gateway, but it does not prove a separate browser/PWA can authenticate, reconnect, receive only permitted state, or execute native Activity/Midi-QOL actions safely.','On the exact Foundry 14.367 / D&D5e 5.3.3 target, build a disposable read-only and typed-request fixture served through a module; test join/auth, permission projection, one safe action, GM-authoritative execution, result receipt, reconnect, duplicate suppression, timeout, and no-cloud operation.','Versioned live receipts for supported and unavailable capabilities, weak-device resource use, hidden-state protection, reconnect/duplicate behavior, and licensing/content scan.','P0','open','runtime','SRC-THINCLIENT-TECH-40'),
('O-043','research','Run Player Flow / Tabletop Ease Mode task and price test','Player confusion is visible, but existing HUD, keyboard, accessibility, and training workarounds may be sufficient and some users dislike additional overlays.','Compare ordinary Foundry, the group''s current training/workaround, Foundry Navigator or an existing HUD where applicable, and a task-driven cockpit using the same novice or returning player tasks.','Time to first correct action, GM interruptions, task completion, onboarding time, accessibility success, player preference, GM purchase authority, repeat use, and actual non-zero price choice.','P0','open','product-research','SRC-PLAYER-FLOW-41'),
('O-044','research','Run Monster Field Guide qualified-GM buyer and price trial','Creature knowledge pain and the 2024 Study hook are plausible, but ANewFoe and manual notes may be sufficient and no direct price evidence exists.','Recruit 10â€“12 GMs with recent knowledge/metagaming incidents; compare the real workaround, Study/manual reveal, and a 20â€“30 second tiered codex demo; ask for $5/$10/$15/$20 or no purchase and a scheduled pilot.','Recent incident, time to useful fact, GM interventions, preference over workaround, non-zero price choice, pilot commitment, repeat use, and reasons for rejection.','P0','open','product-research','SRC-MONSTER-GUIDE-45'),
('O-045','implementation','Build an exact disposable Monster Field Guide fixture','A product demo can hide the hard boundary: per-player hidden knowledge, GM approval, D&D5e Activity/hooks, reconnect, and duplicate suppression.','Use synthetic actors and two users on Foundry 14.367 / D&D5e 5.3.3; test unknown-state projection, Study/equivalent check, tiered reveal, persistence, reconnect, duplicate denial, unauthorized access, and authoritative reread without touching a campaign world.','Versioned live receipt, no hidden-state leak, no unauthorized write, exact capability matrix, and rights/content scan.','P0','open','runtime','SRC-MONSTER-GUIDE-45');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-046','research','Run the Monster Field Guide direct-competition trial','ANewFoe may already be good enough, and a modern-target maintenance gap alone may not create a paying market.','Compare ANewFoe where safely loadable, a manual journal/reveal macro, a minimal Study-only flow, and the evidence/provenance candidate with the same synthetic scenario.','Concrete task win, GM intervention count, hidden-state safety, setup cost, repeat use, non-zero price choice, and scheduled pilot.','P0','open','product-research','SRC-MONSTER-COMP-47');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-047','research','Reopen the fresh search if Monster Field Guide fails the direct-competition gate','A narrow niche, no payment, or â€œmodernized ANewFoeâ€ positioning would not meet the wide-market objective.','If the side-by-side trial produces no preferred workflow, price choice, or pilot, search the next recurring ordinary-player problem instead of implementing a near-clone.','Rejected-candidate record, replacement candidates, buyer evidence, and updated competitive matrix.','P0','open','product-research','SRC-MONSTER-COMP-47'),
('O-048','implementation','Provision synthetic GM and Player3 through native disposable Foundry setup','Startup/setup proof passed, but the fixture has zero Users and the exact hidden-state/permission test cannot be run safely without native account creation.','Use only Foundry''s password-gated native user-management surface on the isolated dbx-test-world; create exactly the synthetic GM and Player3, reread identity/role, then run read-only per-user visibility and permission checks before any candidate mutation.','Two-client target-bound receipt, active-GM/user-role reread, hidden-state projection, unauthorized-read denial, no campaign/Ballad touch, and stopped-state receipt.','P0','open','runtime','SRC-RUNTIME-MONSTER-48');

INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-049','research','Run the World Doctor GM incident, price, and alternative-choice test','World cleanup and preflight pain is concrete, but Foundry backups, current recovery/link tools, CLI utilities, and support communities may be good enough.','Recruit GMs with a recent broken-link, duplicate/orphan, asset, load, or upgrade incident; compare backup/manual/support, current point tools, and a 20â€“30 second evidence-linked diagnosis and reversible repair demo. Ask for $5/$10/$15/$20/$25 or no purchase and a pilot.','Recent incident, minutes lost, diagnosis time, false positives, preferred alternative, non-zero price choice, scheduled pilot, repeat use, and rejection reason.','P0','open','product-research','SRC-WORLD-DOCTOR-49'),
('O-050','implementation','Build a synthetic-defect World Doctor fixture','Static docs and package pages cannot prove that a scan distinguishes missing references from harmless stale data or that a repair is reversible.','Use a disposable Foundry 14.367 / D&D5e 5.3.3 world containing synthetic broken UUID/file paths, orphaned token references, duplicate documents/assets, a missing dependency, and one invalid shape; run read-only scan, snapshot, preview, repair, reread, rollback, and no-write checks.','Exact target capability matrix, evidence-linked findings, no false green, no hidden live-world write, successful rollback, and stopped-state receipt.','P0','open','runtime','SRC-WORLD-DOCTOR-49');

INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-051','research','Run the World Doctor GM price and alternative-choice trial','Upgrade pain is credible, but built-in backup/snapshot, hosting support, and current point tools may be sufficient. No direct World Doctor willingness-to-pay evidence exists.','Recruit qualified GMs with concrete incidents; compare their real workaround and current tools with a 20â€“30 second preflight/repair demo; ask for $15/$25/$39 or no purchase and a disposable-copy pilot.','Recent incident, minutes lost, preferred alternative, diagnosis time, false positives, price choice, pilot commitment, repeat use, and rejection reason.','P0','open','product-research','SRC-WORLD-DOCTOR-50');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-001','permissions','Player3 attempted Wall.update after solving a puzzle.','Let player client update protected Wall directly.','Foundry permissions correctly rejected the write.','Route request to active GM; GM validates and commits.','Deterministic and selected live paths; fresh two-client pending.','SRC-TRIALS'),
('T-002','region-builder','Region Builder settings path failed.','Pass an undeclared items variable into the dialog.','Runtime reference is missing before the UI can open.','Pass explicit collection or remove dependency and add smoke test.','Known defect.','SRC-TRIALS'),
('T-003','teleport','Teleport enabled when registration existed.','Assume registered teleport function proves safe workflow.','Landing, permissions, bounce, rollback, and reset were unproven.','Capability-gate and defer promotion until isolated full-function proof.','Blocked live evidence.','SRC-TRIALS'),
('T-004','schema','Plan design and implementation used different versions.','Allow schema 2.0 documentation and 1.0 implementation to coexist.','Importers/validators can disagree while both appear valid.','Unify version and migrate explicitly.','Reconciliation blocker.','SRC-TRIALS'),
('T-005','automation','Model output omitted kinds, nested fields, flags, or batch items.','Send malformed output directly to Foundry or retry provider blindly.','Provider output is not a Foundry contract; unsafe fields and omissions are ambiguous.','Deterministic normalization, bounded repair, unresolved findings, hard rejection of unsafe fields.','Static hybrid sweep/test evidence.','SRC-TRIALS'),
('T-006','package','Test package passed while source/archive drifted.','Treat green test result as proof of shipped artifact.','Tested and shipped files were not guaranteed identical.','Fingerprint source, tester, stable archive, and commit separately.','Tester provenance passes; stable release gated.','SRC-TRIALS'),
('T-007','spatial','Iggwilv audit found shaped Regions but no behaviors.','Treat geometry and flags as executable progression.','Spatial authoring and runtime logic are separate layers.','Compile and verify behaviors, actors, items, state, and links separately.','Live negative audit.','SRC-TRIALS'),
('T-008','macro','Hardcoded chat macro used UUIDs without runtime proof.','Paste macro into a world and infer portability from syntax.','No isolated test, opaque permissions, stale links, and no rollback.','Native/declarative first; fixed reviewed adapter and no-write probe only when needed.','Historical unsafe attempt.','SRC-TRIALS'),
('T-009','activities','Additional Activities were considered for multi-step features.','Create new Activity types for every procedural step.','Midi already handles many resolution steps and can link secondary/triggered Activities.','Activity represents action; Midi represents resolution; Additional Activity only for unsupported verb.','Architecture finalized, exact-stack proof pending.','SRC-COMPILE'),
('T-010','maps','AI map artwork invented topology or perspective.','Use text-only image generation as map authority.','Image renderer cannot guarantee geometry, scale, doors, or exact symbols.','Spatial Blueprint and graybox precede rendering; deterministic compositing fallback.','Architecture locked.','SRC-CHAT-COMPILER'),
('T-011','m0','Implementation began without an exact Foundry runtime.','Start with document mutation or infer runtime behavior from source and package metadata.','The target runtime has not been probed, so mutation and capability claims would be unverified.','Build the contract spine and no-op module first; keep execution and binding resolution unavailable until readiness evidence exists.','Static/deterministic M0 evidence; live runtime proof pending.','SRC-M0-IMPLEMENTATION'),
('T-012','market-product-selection','Player Turn Coach appeared attractive but faced direct feature overlap.','Treat a contextual action panel as a complete paid product after observing player combat friction.','Argon, Stylish Action HUD, Corn''s Combat Reminders, Action Keeper, and turn-time tooling cover adjacent jobs; the remaining UX gap is not yet proven to support a separate purchase.','Demote coach to a supporting feature and test Session Rescue as the GM-paid wedge.','Research evidence; buyer behavior pending.','SRC-PRODUCT-RESEARCH'),
('T-013','market-product-selection','Broad Session Rescue overlapped with AI continuation, campaign planning, and backups.','Position the product as a general rescue generator or campaign-memory assistant.','Familiar, World & Campaign Builder, SessionFlow, Party Operations, GMhub, RPG Tracker, Foundry backups, and document backup modules cover adjacent broad workflows.','Narrow to Campaign Safe Mode: typed checkpoint, temporary branch, semantic diff, selective merge/discard, re-entry brief, and receipt.','Research evidence; buyer and exact-runtime behavior pending.','SRC-CONTINUITY-PASS'),
('T-014','portability','A universal live-sync claim would overstate platform capability.','Use the Foundry branch model as if Roll20 and Fantasy Grounds expose the same mutation and persistence boundaries.','Foundry offers Document serialization/validation/operations; Roll20 Mods are creator/Pro-bound; Fantasy Grounds stores campaign state in XML and extends with Lua/XML.','Export a neutral packet and build explicit read-only/import adapters before any cross-VTT live writes.','Research evidence; adapter implementation pending.','SRC-PORTABILITY-PASS'),
('T-015','market-pricing','Safe Mode could be purchased as an occasional emergency tool.','Assume the ability to recover one bad session is enough to sustain a paid product.','Foundry users have free core backups and free planning/memory alternatives; broad AI continuation monetizes recurring service while Safe Mode is episodic.','Add an every-session checkpoint/ledger surface, test one-time pricing after use, and reject stated-interest-only evidence.','Research evidence; purchase behavior pending.','SRC-PRICING-PASS'),
('T-016','market-rejection','A generic campaign safety product appeared differentiated by risk reduction.','Treat backup, deletion recovery, validated live edits, and campaign state tracking as unserved jobs.','Foundry backups, Recycle Bin, World CLI, Campaign Forge, and duplicate-world practices cover adjacent safety and continuity needs.','Require the semantic branch/merge workflow to win a direct alternative comparison; reject the product if buyers prefer ordinary recovery tools.','Research evidence; buyer comparison pending.','SRC-REJECTION-PASS'),
('T-017','market-portability','Player pain suggested a broad companion product with wide demand.','Treat mobile sheets, onboarding, accessibility, party inventory, trading, and navigation as an unserved cross-VTT category.','Multiple current Foundry packages and companion apps already cover these jobs, while the GM or host usually controls the purchase.','Retain player-safe re-entry as a feature of Campaign Safe Mode and use a neutral session packet as the first portability surface.','Research evidence; buyer and usability comparison pending.','SRC-PLAYER-PASS'),
('T-018','market-positioning','Campaign Safe Mode was useful but not obviously desirable in a marketplace browse.','Lead with generic safety, rollback, backups, or technical branch terminology.','Those terms describe infrastructure and require explanation; visual marketplace competitors communicate immediate outcomes.','Reframe as Campaign Continuity with a visible disruption-to-branch-to-merge demo, free checkpoint/export, and trust-building proof.','Research evidence; message test pending.','SRC-MARKETING-PASS'),
('T-019','market-productization','Campaign Continuity lacked a visually immediate hero moment.','Market the branch engine as a settings utility or invisible insurance product.','Current premium Foundry products lead with cinematic transformations and player-visible effects, so the recovery value was hard to see in a browse.','Propose a branch-backed Canon & Branch Board with semantic diff, player-safe Re-entry Card, and Canonize action; reject if it becomes merely a prettier recap.','Research evidence; hero-artifact test pending.','SRC-HERO-ARTIFACT-PASS'),
('T-020','market-selection','Continuity disruption pain may not create enough purchase urgency.','Assume absent-player and off-script problems are more valuable than update/migration safety without comparing recent incidents.','Groups often use one-shots, ghost characters, or cancellation, while update/data-loss failures create immediate game-night risk but have free backup substitutes.','Compare Campaign Continuity and Campaign Guardian as separate offers using recent pain and purchase choice.','Research evidence; head-to-head buyer test pending.','SRC-URGENCY-PASS'),
('T-021','market-rejection','A visually attractive Guardian, Replay, or improvisation suite appeared more marketable than Continuity.','Choose a product because its demo is flashy or its fear message is strong.','Foundry/Forge recovery, Battle Replay, and current encounter/improvisation modules already cover the broad promises.','Retain only the semantic non-combat branch/merge hypothesis and force a direct alternative comparison.','Research evidence; buyer and runtime proof pending.','SRC-REJECTION-23'),
('T-022','technical-feasibility','The Foundry API appeared capable enough to make branch/merge safe.','Infer product readiness from toObject, clone, validation, update, and hook documentation.','The API exposes useful primitives but does not provide universal atomic rollback, state coverage, or exact-world multi-document proof.','Build a disposable exact-stack fixture with staged authority, failure injection, authoritative reread, and explicit unsupported-state receipts.','Research evidence; exact runtime prototype pending.','SRC-TECH-PASS'),
('T-023','market-attention','Campaign Continuity was made more visual with Canon & Branch Board.','Use a timeline/branch board as the storefront hero and assume visual polish creates demand.','Current Foundry dashboards, timelines, clue boards, quest logs, and organizer modules make the visual surface legible but not necessarily novel; the operational payoff is still episodic.','Keep the branch board as an internal/supporting surface and reopen the product search.','Research evidence; buyer attention and purchase choice pending.','SRC-ATTENTION-PASS'),
('T-024','market-product-selection','Adventure Capsules appears more eye-catching than Campaign Continuity.','Move immediately to premium one-shot content because the listing can show scenes, handouts, and reveals.','Premium adventures and map/content packs are direct competitors; rights, prep labor, repeat purchase, and cross-VTT portability are unresolved.','Run a direct candidate pass before implementation; retain Campaign Continuity mechanics only as reusable infrastructure.','Research evidence; competitor and buyer choice pending.','SRC-ATTENTION-PASS'),
('T-025','market-adventure','Generic Adventure Capsules overlap with current ready-to-run premium content.','Treat prepared maps, scenes, handouts, music, branching, and cinematic effects as a new product moat.','Dragonshorn, Drop-in Dungeons, Prepared! 2, Boss Loot, Rultmoork, and other publishers already sell those outcomes.','Narrow to Adaptive Drop-In Capsules for variable attendance and no-canon return to the campaign.','Research evidence; buyer attendance wedge pending.','SRC-ADVENTURE-PASS'),
('T-026','market-portability','A premium Foundry adventure can be exported to another VTT without loss.','Assume Foundry Actors, Items, Scenes, Journals, macros, and animation dependencies have equivalent destinations.','Foundry-specific automation and system data do not port cleanly; only the narrative, handout, asset, and neutral graph layers are naturally portable.','Separate neutral capsule packet from Foundry projection and test one read-only export.','Research evidence; rights and portability fixture pending.','SRC-ADVENTURE-PASS'),
('T-027','technical-evidence','The exact target runtime was missing or only hypothetical.','Infer technical feasibility from repository tests, package manifests, or API documentation.','The local preflight found the exact target manifests and installed DiceBox package, but it did not run Foundry or prove live behavior.','Use the available bounded disposable fixture for a read-only/live-readiness probe; do not upgrade evidence class until the live receipt exists.','Deterministic manifest evidence; live runtime probe pending.','SRC-RUNTIME-AVAILABILITY'),
('T-028','market-positioning','A better name could make Campaign Continuity desirable without changing the product.','Rename Safe Mode to Campaign Continuity and rely on a Canon & Branch Board screenshot.','The underlying benefit remained episodic, reactive, and adjacent to free recovery workflows; visual polish did not create an obvious buyer outcome.','Move the storefront promise to Game Night Rescue and test a concrete attendance-to-play sequence.','Research evidence; buyer choice pending.','SRC-EYE-CATCHING-28'),
('T-029','market-competition','Cross-world one-shot continuity is an unoccupied attendance wedge.','Assume a new module owns the entire absent-player/side-session workflow.','Omnipresence already synchronizes characters, journals, and hotbars across worlds and advertises one-shot use.','Differentiate on finished no-canon content, present-player launch, and clean return rather than synchronization alone.','Research evidence; buyer choice and runtime workflow pending.','SRC-EYE-CATCHING-28'),
('T-030','market-payer','Game Night Rescue was initially framed as a broad home-game purchase.','Use attendance anecdotes as proof of a paying market.','Home tables often resolve absences with quorum, ghosting, backup pilots, free one-shots, or rescheduling; paid/professional and rotating hosts have clearer measurable value.','Test the booked-session/ROI message with qualified payer cohorts before continuing the broad product thesis.','Research evidence; payer pilot pending.','SRC-PAYER-SEGMENT-29'),
('T-031','market-competition','DMF appeared to compete only with plain-language item generators.','Assume item creation alone defines the market and that a generated item document proves the job is done.','The local feature scan shows DMF''s differentiator is cross-module automation compilation, review, dependency routing, and verification; the direct competitor''s public feature surface emphasizes item documents and JSON export.','Test Custom Item Workshop against Auto Maker, native forms, Item Creator, free macros, and community help with real custom-item incidents.','Research evidence; buyer test and fresh live item proof pending.','SRC-DMF-MARKET-30'),
('T-032','market-positioning','Automaker''s direct-item workflow could make DMF''s compiler surface feel unnecessarily complex.','Lead with schemas, automation recipes, or raw code before proving a basic item can be created quickly.','Automaker makes direct insertion, history/retry, and usage allowance the visible experience; DMF must match the basic path and reserve complexity for the advanced behavior review.','Run the three-path complex-item comparison and expose the automation layer only when it saves setup or makes behavior verifiably work.','Research evidence; side-by-side buyer trial pending.','SRC-AUTOMAKER-COMPARE-31'),
('T-033','market-portability','A single compiled DMF item cannot be assumed to run unchanged across VTTs.','Treat Foundry D&D5e Activities and Midi-QOL/DAE/Item Macro output as a universal item format, or promise live Roll20/Fantasy Grounds writers before adapter proof exists.','The platforms expose different runtime boundaries: Foundry documents/activities, Roll20 campaign-local Pro scripts, and Fantasy Grounds ruleset/XML/Lua extensions.','Ship/export a neutral recipe and receipt first; build separately verified projections and explicit capability matrices for any secondary VTT.','Research evidence; portability fixture and buyer choice pending.','SRC-DMF-PORTABILITY-32'),
('T-034','market-selection','Backup and compatibility metadata do not prove that a campaign will play after an upgrade.','Treat a successful backup, green compatibility badge, or module-profile restore as a behavioral safety certificate.','Core tools protect recoverability and configuration but do not exercise the user''s active scene, character, item, journal, macro, or module-critical paths on the candidate stack.','Prototype a disposable world rehearsal with selected smoke tests and an evidence-labeled receipt; require a real buyer price choice before implementation.','Research evidence; exact fixture and buyer trial pending.','SRC-UPGRADE-GUARDIAN-34'),
('T-035','technical-product','An in-world module cannot safely rehearse its own future runtime.','Attempt to copy or migrate an open campaign, swap the active Foundry executable, or issue a universal green certificate from inside the world.','The world/runtime is open and may have external package-owned state; the platform''s setup-time package and backup boundaries are safer.','Use a local setup companion and closed disposable world, with an optional probe module and explicit not-exercised/entitlement/restore evidence.','Research evidence; local rehearsal fixture pending.','SRC-UPGRADE-TECH-35'),
('T-036','market-selection','A generic compatibility report is easy to replace with core tools or hosting.','Sell red/amber/green package metadata as the complete product and ignore the user''s current version, world boundaries, and launch workflow.','Foundry already supplies compatibility checks/backups and hosting services supply version choice/snapshots; the remaining local wedge is per-world runtime locking and reproducible launch.','Run the alternative-choice and price test; reject if users prefer waiting, manual portable installs, or hosting.','Research evidence; empirical buyer test pending.','SRC-RUNTIME-LOCKER-36');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-037','market-selection','Performance pain is broad but a generic monitor is already replaceable.','Treat a live FPS chart, a low/medium/high profile, token-render optimization, or module bisection as a new product by itself.','Current competitors cover those point solutions.','Use a guided incident timeline that correlates player/client and world signals, reproduces safely, and applies a reversible profile while preserving privacy.','Research evidence; buyer trial and technical trace fixture pending.','SRC-SESSION-HEALTH-37');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-038','market-selection','Foundry mobile access is a visible player problem.','Assume a new touch character sheet or mobile app is an open market.','Swipe, Sheet Only, Tabletop Helpers, Companion Bridge/VTT Companion, PocketScroll, and Roll20 already occupy the obvious mobile surfaces.','Test only a no-install, low-bandwidth browser relay that deliberately avoids full-canvas rendering and proves better reach or setup for weak devices.','Research evidence; device fixture and buyer choice pending.','SRC-MOBILE-RELAY-38');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-039','market-selection','A current mobile-companion thread contains explicit â‚¬15â€“â‚¬25 price interest.','Treat that thread and a â‚¬15 lifetime competitor as proof that any new mobile product will sell.','The evidence is self-reported and the full mobile surface is already occupied by products with real implementations and support obligations.','Test only the differentiated thin-client boundary on a weak device, then compare actual one-time price choice against existing companions and the group''s workaround.','Research evidence; device fixture, automation fidelity, and buyer choice pending.','SRC-PAYER-MOBILE-39');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-040','technical-product','Official Foundry docs make a module-mediated relay look feasible.','Treat the module socket, public API, and permissions documentation as proof that a standalone browser/PWA can authenticate, reconnect, project hidden-state-safe data, and execute all desired player actions.','The docs establish platform primitives but not the exact external-client boundary, device performance, native system/module automation fidelity, or cross-VTT equivalence.','Keep Foundry authoritative; serve a minimal relay through the module, accept only typed capability-gated requests, use documented public surfaces, return verified receipts, and fail closed for unsupported actions. Test it in a disposable exact-stack fixture before product selection.','Research evidence; exact runtime fixture and buyer test pending.','SRC-THINCLIENT-TECH-40');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-041','market-selection','Player confusion and accessibility friction look like an open market.','Add another HUD, permanent action toolbar, or generic keyboard/accessibility patch and assume reducing clicks means buyers will pay.','Current packages cover slices of the job, and recent reports show that multiple interfaces can create duplicate actions, bloat, and more choice overload; some groups solve the problem with training or simpler VTTs.','Test a minimal per-player task cockpit that hides choices, guides one correct next action, supports text/keyboard/screen-reader paths, and compares directly with existing HUDs and ordinary training.','Research evidence; task fixture and buyer choice pending.','SRC-PLAYER-FLOW-41');
INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-042','market-selection','Player Flow has recurring pain but lacks standalone purchase urgency.','Treat official tutorials, a guided cockpit, or a premium beginner world as proof that a generic player-flow module will sell.','Foundry already provides free player orientation and GM tutorials; groups also use training sessions, mini-campaigns, HUDs, and simpler VTTs. The premium Beginner Box monetizes content plus onboarding rather than onboarding alone.','Reject the standalone product and preserve task-graph/guidance/accessibility components for a stronger paid surface such as the thin relay or bundled content.','Research evidence; standalone buyer price test not justified until a new bundle hypothesis exists.','SRC-PLAYER-FLOW-42');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-043','market-selection','Drawing and collaborative whiteboard demand appears to be an open market.','Treat an Excalidraw-like layer or generic better-drawing module as a new wide-market product.','Native Foundry plus current drawing, wall, dungeon, Owlbear, Miro, and MapForge products cover the obvious buyer jobs.','Reject the standalone category; retain only a narrower geometry/export audit as a reusable creator-facing component and reopen the player-market search.','Research evidence; no buyer trial justified for generic drawing.','SRC-DRAWING-43');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-044','market-selection','Progressive monster knowledge has a clear visual demo and a 2024 D&D Study hook.','Treat ANewFoe, PF2E Bestiary Tracking, community interest, or player enthusiasm as proof of a paying D&D5e market.','Category evidence does not identify the payer, prove current D&D5e support, or establish a price; manual notes and GM approval may remain sufficient.','Test qualified GMs against their real workaround with a silent tiered-reveal demo, real price choices, and scheduled pilots.','Research evidence; buyer validation pending.','SRC-MONSTER-GUIDE-44');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-045','technical-product','A per-player creature codex looks simple enough to build from sheets or chat cards.','Expose creature details directly to every client or assume a Study button and generic reveal card proves safe automation.','Hidden knowledge, GM approval, current D&D5e hooks, reconnect, duplicate requests, and user-owned/licensed content boundaries are separate failure modes.','Use synthetic actors in an exact disposable fixture, keep Foundry authoritative, return evidence-labeled tier receipts, and fail closed for unsupported actions or content.','Research evidence; exact runtime fixture pending.','SRC-MONSTER-GUIDE-45');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-046','market-selection','Simple trade and campaign-memory requests appear to be wide open markets.','Treat a focused trade window, treasury, campaign wiki, or AI memory layer as a new product despite recurring user pain.','Current trade/loot/shop modules and current campaign codex/AI memory/external note tools already occupy the jobs.','Reject broad logistics/memory products and retain only their permission, relationship, receipt, and note primitives as reusable assets.','Research evidence; no fresh buyer trial justified for generic surfaces.','SRC-LOGISTICS-MEMORY-46');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-047','market-selection','Monster Field Guide appears new because ANewFoe is old and PF2E has a current analog.','Assume a v14 update and Study button are enough differentiation.','ANewFoe already covers the baseline workflow and the buyer may prefer a journal, macro, or no formal tracking.','Run a direct ANewFoe/manual/Study/evidence-provenance comparison with qualified GMs, real price choice, and scheduled pilot before any implementation.','Research evidence; direct buyer comparison pending.','SRC-MONSTER-COMP-47');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-048','technical-product','Exact Foundry startup and setup are available, but user-specific knowledge safety is not yet observed.','Treat a process-ready receipt and join page as proof that per-player Monster Field Guide behavior is feasible.','The isolated fixture contains zero users; per-user hidden-state, active-GM authority, and permission denial require native synthetic-user setup and a second client.','Record startup as PASS, keep product readiness blocked, provision only through native setup, and run the two-client read/permission test before implementation.','Exact target startup/setup evidence; user-specific runtime fixture pending.','SRC-RUNTIME-MONSTER-48'),
('T-049','market-selection','A fresh world-safety search can be mistaken for backup, deduplication, or generic compatibility monitoring.','Package World Doctor as a backup manager, red/amber/green badge, duplicate finder, or list of warnings.','Foundry core and current modules already cover those pieces, while GMs need evidence of the specific affected object and a reversible repair plan.','Test the narrow evidence-linked preflight: scan, explain, snapshot, preview, repair, authoritative reread, and rollback against synthetic defects; reject if a current point tool or manual workflow is preferred.','Research evidence; buyer choice and exact synthetic-defect fixture pending.','SRC-WORLD-DOCTOR-49');

INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-050','market-selection','World Doctor may be a credible pain reliever but has no direct buyer price evidence and overlaps platform recovery features.','Assume update incidents imply demand and package the candidate as a backup or compatibility dashboard.','Foundry already supplies backup/snapshot/rollback and support supplies manual compatibility guidance; community pricing evidence favors buy-once but is not product-specific.','Test only one-time $15/$25/$39 anchors for evidence-linked preflight diagnosis and reversible repair with qualified GMs and a disposable-copy pilot.','Research evidence; direct price choice, pilot, and fixture safety pending.','SRC-WORLD-DOCTOR-50');

INSERT OR REPLACE INTO kb_milestones(milestone_id,milestone,goal,deliverables,exit_gate,dependencies,status,source_id) VALUES
('M0','Repository and contract skeleton','Create DiceBox architecture without meaningful Foundry mutation.','TypeScript/ESM packages; IDs; schemas; result envelopes; version constants; tests; ADRs; AGENTS.md.','No arbitrary patch type or upward adapter dependency; tests pass.','None','ready','SRC-FOUNDATION'),
('M1','RuntimeProfile and CapabilityRegistry','Discover exact environment and safe capabilities.','Foundry/system/module/settings/document signatures; capability states; adapter registry; Safe Mode.','Missing/unsupported capability returns unavailable without mutation.','M0','planned','SRC-FOUNDATION'),
('M2','Foundry Bridge shell','Load a no-op DiceBox module and expose semantic read-only API.','Manifest; lifecycle; API facade; HookIngress; health/describe/supports; User.query skeleton.','Clean Foundry 14.367 + D&D5e 5.3.3 load with no bridge errors.','M0,M1','planned','SRC-FOUNDATION'),
('M3','Identity/settings/document slice','Create a tiny idempotent set of CA-managed Documents.','Identity/binding generations; settings profile; Folder/Journal/Actor/Item/Scene shell creation; read-back receipts.','Disposable world receives exact identity-bound documents idempotently.','M2','planned','SRC-FOUNDATION'),
('M4','Links and SRD reuse','Resolve exact links and reuse sources without fuzzy matching.','Link compiler; fromUuid resolver; compendium index; source/rules profile; sample links.','Link closure and upstream identity survive clean import.','M3','planned','SRC-FOUNDATION'),
('M5','Media and asset pipeline','Manage approved assets and deployment bindings.','Media registry; hashes; variants; references; closure; client checks; no cleanup.','Background/token/handout assets deploy and read back.','M3,M4','planned','SRC-FOUNDATION'),
('M6','Spatial Scene slice','Compile one spatial blueprint into a minimal playable room.','Blueprint validator; projection; Scene/Level/Wall/Region/token anchors; topology/read-back/player fixture.','Same geometry at multiple raster densities; player checks pass.','M3,M4','planned','SRC-FOUNDATION'),
('M7','Furnishing and image integration','Render/furnish without changing frozen geometry.','Constraint solver ports; baked/placeable policy; image ingestion; deterministic compositor; validation hooks.','Room art/furnishing changes do not alter spatial truth.','M5,M6','planned','SRC-FOUNDATION'),
('M8','Automation runtime','Select and execute bounded Activity/Effect/Region mechanics.','Activity/Midi selection; authority; transaction ledger; representative native command; optional adapters.','Player-triggered mechanic executes once via authorized owner and survives retry/reconnect.','M1,M2,M3,M6','planned','SRC-FOUNDATION'),
('M9','Release compiler','Build deterministic campaign bundles for clean worlds.','BuildPlan; typed packs; closure; bootstrap; diff; selective repair.','Fresh world bootstraps fixture and restarts healthy.','M4,M5,M6,M8','planned','SRC-FOUNDATION'),
('M10','Live Sync','Reconcile managed definitions without overwriting play state.','Ownership/provenance; conflict planner; sovereignty guards; selective repair; migrations.','Played fixture preserves runtime and foreign state through update.','M8,M9','planned','SRC-FOUNDATION'),
('M11','Certification','Issue blocker-based Ready-to-Play certificate.','Validation suite; exact stacks; GM/player fixtures; failure injection; performance; backup/restore.','Zero unresolved required blockers on frozen release fingerprint.','M9,M10','planned','SRC-FOUNDATION');

