INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,tags) VALUES
('F-806','implementation','', 'Star*Tup has a deterministic disposable fixture contract','Fixture plans bind a caller-supplied ID, exact target metadata, GM/Player3 contexts, ordered lifecycle stages, and explicit no-write/no-raw-data flags without generating nondeterministic identity.','project','deterministic','active','SRC-STARTUP-FIXTURE-171','startuptup,fixture,deterministic,gm,player3'),
('F-807','safety','', 'Fixture observations are redacted by contract','Star*Tup fixture observations record stages, resource counts, long-task counts, unsupported labels, and notes while rejecting raw Foundry IDs, documents, module payloads, and asset bytes.','project','created_document','active','SRC-STARTUP-FIXTURE-171','fixture,redaction,no-raw-data,safety'),
('F-808','safety','', 'Incomplete fixture evidence stays blocked','A missing client context, missing lifecycle stage, or explicitly blocked observation prevents an observed receipt while preserving no-write guarantees.','project','blocked','active','SRC-STARTUP-FIXTURE-171','fixture,blocked,evidence,safety'),
('F-809','verification','', 'Star*Tup M0â€“M2 verification passes eight tests','The standalone package passes eight Node tests, including deterministic fixture observed and blocked cases and explicit client/world profile scope, plus syntax checks.','project','deterministic','active','SRC-STARTUP-FIXTURE-171','tests,verification,m0,m1,m2'),
('F-810','architecture','', 'DiceBox compatibility is documented without importing the dirty checkout','Star*Tup preserves receipt and fixture vocabulary while keeping the standalone package dependency-free; the existing media, attestation, and FilePicker contracts remain reserved for later slices.','project','created_document','active','SRC-STARTUP-FIXTURE-171','compatibility,dicebox,standalone,provenance'),
