INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-MINING-TIMING-RUNTIME-SMOKE-179','Regionwright Mining v0.2.0 installed-server smoke','verification','project','Installed-file SHA-256 comparison plus exact Foundry 14.367 regionwright-testmap server restart and HTTP module reads','active','C:/Users/rujie/AppData/Local/FoundryVTT/Data/modules/regionwright-mining','2026-10-03','regionwright-mining 0.2.0 / Foundry 14.367 / port 30000','All seven timing-puzzle deployment files matched durable source. After resolving a stale data-directory lock from the first restart attempt, Foundry relaunched with --world=regionwright-testmap and served module v0.2.0, socket=true, timing UI code, and timing engine code. This is server/deployment evidence, not player gameplay certification.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-860','mining',NULL,'Regionwright Mining v0.2.0 is installed and served by the exact Foundry runtime','The installed seven changed files match durable source byte-for-byte. Foundry 14.367 relaunched regionwright-testmap on port 30000 and HTTP reads returned module version 0.2.0 with socket=true plus the new timing UI/engine code; player gameplay remains uncertified.','project','safe_use','provisional','SRC-MINING-TIMING-RUNTIME-SMOKE-179',NULL,'mining,timing,deployment,foundry,v0.2.0,server-smoke');
INSERT OR REPLACE INTO kb_trials(trial_id,area,symptom,attempted_approach,failure_cause,correction,evidence_status,source_id) VALUES
('T-197','Foundry restart','The first immediate relaunch after stopping the regionwright-testmap process exited and port 30000 was not listening.','Stop the prior Foundry PID and immediately start the same executable/world command.','The prior Foundry data-directory lock had not yet released, so the replacement correctly refused to start with a directory-locked fatal error.','Reread process/port/lock state, avoid blind retry, then perform one clean relaunch only after no Foundry process/listener/lock remained.','Clean relaunch succeeded; PID 31480 listened on port 30000 and served regionwright-mining v0.2.0.','SRC-MINING-TIMING-RUNTIME-SMOKE-179');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
