-- Regionwright Mining rendered-diameter timing correction accepted 2026-10-03.
INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-MINING-DIAMETER-185','Regionwright Mining rendered-diameter timing correction','conversation','project','Direct user acceptance of rendered-size scoring after visual playtest','active','docs/REGIONWRIGHT-MINING-ROADMAP.md','2026-10-03','regionwright-mining 0.2.4 source','The moving ring must physically enter the tiny Perfect center. Use a 250 px base ring with 0.08 minimum scale (20 px), and score from rendered diameter so visual geometry and gameplay cannot drift.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-866','mining',NULL,'Mining timing score derives from rendered ring diameter','The timing ring renders from 250 px down to 20 px. Strike score is determined from rendered diameter: <=26 Perfect, <=62 Excellent, <=103 Great, <=149 Good, <=200 Glancing, and >200 Miss.','project','canonical','locked','SRC-MINING-DIAMETER-185','F-865','mining,timing,diameter,perfect,geometry,v0.2.4');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-403','mining timing geometry','Make rendered ring diameter the scoring source of truth and lower the pulse floor to 20 px. Keep Perfect restricted to <=26 px even though the visible center bullseye is 38 px.','The prior ratio model could award or display a result that did not match what the player could physically see. Diameter-based scoring keeps visual and mechanical thresholds coupled while preserving a rare Perfect window.','project','locked','user','SRC-MINING-DIAMETER-185','Tune diameter bands only after live playtest.');
