INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-872','mining',NULL,'Mining timing difficulty scales by ore','Common Copper/Tin/Iron use 1500/1350/1200 ms; Silver 1400/1250/1100; Gold 1300/1150/1000; Platinum 1200/1050/900; Mithral 1100/950/825; Hizagkuur 1000/875/800; Arandur 950/850/800. Score geometry and 0-5 yield remain unchanged.','project','canonical','locked','SRC-MINING-DIFFICULTY-HUD-190',NULL,'mining,difficulty,ore,timing'),
('F-873','mining',NULL,'Nine-ore fixed price catalogue','Mineable ore prices are Iron 1 sp, Tin 3 sp, Copper 5 sp, Silver 2 gp, Gold 10 gp, Platinum 25 gp, Mithral 100 gp, Hizagkuur 625 gp, and Arandur 1,000 gp per one-pound unit. Adamantine is excluded from the mineable catalogue.','project','canonical','locked','SRC-MINING-DIFFICULTY-HUD-190',NULL,'mining,ore,prices,catalog'),
('F-874','mining',NULL,'Mining and Fishing share a Gathering HUD','The Regionwright fishing HUD will become a tabbed Regionwright Gathering HUD. Fishing preserves its current setup/test surface; Mining adds ore configuration and all-ore player testing through the Mining module public API.','project','canonical','locked','SRC-MINING-DIFFICULTY-HUD-190',NULL,'mining,fishing,hud,integration');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-406','mining difficulty and HUD','Scale mining difficulty by pulse speed only, add all nine ores to testing, and combine Fishing/Mining setup into the existing Regionwright HUD shell.','One scoring geometry keeps player learning consistent; speed creates ore-specific challenge. One gathering HUD avoids duplicate floating panels and can integrate modules through public APIs.','project','locked','user','SRC-MINING-DIFFICULTY-HUD-190','Review after live GM HUD and non-GM remote-test observation.');
