INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-MINING-SCOREZONES-195','Mining high-tier scoring-zone retune','conversation','project','Direct user playtest direction','active','docs/REGIONWRIGHT-MINING-ROADMAP.md','2026-10-04','mining scoring zones v2','Gold and higher should have progressively smaller success zones and larger failure zones in addition to faster pulses.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-878','mining',NULL,'High-tier ores use progressively tighter scoring geometry','Copper, Tin, Iron, and Silver retain score thresholds 26/62/103/149/200 px. Gold uses 25/56/92/132/175; Platinum 24/52/84/120/160; Mithral 23/48/76/108/145; Hizagkuur 22/44/70/98/132; Arandur 22/40/64/90/120. Thresholds are maximum rendered diameters for scores 5 through 1; larger rings score 0.','project','canonical','locked','SRC-MINING-SCOREZONES-195',NULL,'mining,difficulty,scoring,gold,platinum,mithral,hizagkuur,arandur');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-408','high-tier mining scoring zones','Starting at Gold, shrink every positive-scoring diameter band progressively by ore tier while keeping low-tier geometry unchanged.','High-value ore should require both reaction speed and precision; enlarging the miss zone prevents upper tiers from remaining forgiving even when pulses are fast.','project','locked','user','SRC-MINING-SCOREZONES-195','Review after live tester pass.');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-468','implementation','Implement high-tier ore-specific score bands','Gold and higher currently inherit the same success geometry as common ores.','Add difficulty-aware rendered-diameter score bands, update live/strike scoring and tests, deploy/restart, and verify served values.','Passing tests, installed-source hashes, served v0.3.2 score profiles, then live tester feedback.','P0','in_progress','runtime','SRC-MINING-SCOREZONES-195');
