INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-879','mining',NULL,'Mining v0.3.2 serves tighter Gold-and-higher success zones','Foundry serves v0.3.2 with Gold thresholds 25/56/92/132/175 px, Platinum 24/52/84/120/160, Mithral 23/48/76/108/145, Hizagkuur 22/44/70/98/132, and Arandur 22/40/64/90/120 for scores 5 through 1. The visible target rings shrink with those profiles and rings beyond the score-1 boundary miss.','project','safe_use','provisional','SRC-MINING-SCOREZONES-BUILD-196',NULL,'mining,difficulty,scoring,zones,v0.3.2,deployment');
