INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-881','mining',NULL,'Mining v0.3.3 serves deterministic center acceleration','Foundry serves v0.3.3 with TIMING_CENTER_ACCELERATION 0.30 and q = r + 0.30*r*(1-r). Mining runtime applies the transform each animation frame before rendering/scoring. Full pulse duration, endpoints, ore speed profiles, and ore-specific score zones are unchanged.','project','safe_use','provisional','SRC-MINING-CENTER-ACCEL-BUILD-198',NULL,'mining,timing,acceleration,v0.3.3,deployment');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-469','implementation','Implement center-accelerating mining pulse','Resolved in served Mining v0.3.3.','Use the Gathering HUD tester across common and legendary ores and retune the 0.30 acceleration only from playtest feedback.','Subjective player feedback on whether the center quickening is noticeable, learnable, and appropriately harder.','P0','closed','runtime','SRC-MINING-CENTER-ACCEL-BUILD-198');
-- Regionwright Hunting & Gathering product/HUD architecture 2026-10-04.
INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-HG-HUD-199','Regionwright Hunting & Gathering mini-HUD architecture','conversation','project','Direct user architecture decision plus Puzzle HUD source review','active','docs/REGIONWRIGHT-HUNTING-GATHERING-ROADMAP.md','2026-10-04','hunting-gathering architecture v1','Standalone umbrella module with a compact GM HUD modeled on the Puzzle HUD; Fishing and Mining delegate to existing APIs while Hunting and Gathering are built.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-882','hunting-gathering',NULL,'Hunting & Gathering is a standalone Regionwright module','Regionwright: Hunting & Gathering will own Hunting, Fishing, Mining, and Gathering as one environmental-resource product. Existing Fishing and Mining remain authoritative during scaffold/migration.','project','canonical','locked','SRC-HG-HUD-199',NULL,'regionwright,hunting,gathering,fishing,mining,module'),
('F-883','hunting-gathering',NULL,'Hunting & Gathering uses a compact GM mini-HUD','The new module uses a compact active-GM DialogV2 HUD modeled on the Puzzle HUD. It owns orchestration only: activity tabs, selected Region context, setup/clear actions, and test targeting; subsystem catalogs/gameplay remain in their APIs until migrated.','project','canonical','locked','SRC-HG-HUD-199',NULL,'regionwright,hud,dialogv2,architecture');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-410','Hunting & Gathering package architecture','Create regionwright-hunting-gathering with a small Puzzle-HUD-style GM interface and runtime adapters to Fishing and Mining; keep Hunting/Gathering disabled until implemented.','This creates the final product boundary without prematurely merging proven subsystem logic or copying Studio complexity.','project','locked','user','SRC-HG-HUD-199','Review after the v0.1.0 scaffold and first Hunting design pass.');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-470','implementation','Scaffold Regionwright Hunting & Gathering mini-HUD','The umbrella module and its compact HUD do not yet exist.','Create source package, Fishing API bridge hooks, tests, build script, and dist artifact without removing legacy Fishing/Mining controls.','Passing source tests/build and source-dist hash agreement.','P0','in_progress','runtime','SRC-HG-HUD-199');
-- Regionwright Hunting & Gathering v0.1.0 scaffold checkpoint 2026-10-04.
INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-HG-HUD-BUILD-200','Hunting & Gathering v0.1.0 mini-HUD scaffold checkpoint','verification','project','New module tests, full Regionwright regression suite, build output, and source-dist hash agreement','active','Region Editor/hunting-gathering + dist/regionwright-hunting-gathering','2026-10-04','regionwright-hunting-gathering 0.1.0 / regionwright-fishing source 0.1.17','Built but intentionally not cut over live. H&G owns a compact four-tab GM DialogV2 HUD; Fishing/Mining delegate to existing APIs; Hunting/Gathering are planned placeholders. Fishing source exposes rarities and remote test through its public API for the future H&G shell.'),
('SRC-HG-HUD-REGRESSION-201','Regionwright full regression after H&G scaffold','verification','project','npm test','active','Region Editor tests','2026-10-04','251/251 tests passing','Full Regionwright suite passed after adding H&G tests and Fishing API bridge.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-884','hunting-gathering',NULL,'Hunting & Gathering v0.1.0 scaffold is built but not live','The Region Editor source and dist contain regionwright-hunting-gathering v0.1.0 with a compact four-tab GM HUD. Fishing and Mining setup/test controls delegate through their public APIs; Hunting and Gathering display explicit planned states. The package has not been cut over or enabled in the live Foundry world, and legacy controls remain untouched.','project','safe_use','provisional','SRC-HG-HUD-BUILD-200',NULL,'regionwright,hunting,gathering,hud,scaffold,v0.1.0'),
('F-885','hunting-gathering',NULL,'H&G scaffold passes full Regionwright regression','The H&G scaffold plus Fishing API bridge passes 251 of 251 Regionwright tests, and source/dist hashes match for the new H&G module and Fishing v0.1.17 build.','project','safe_use','provisional','SRC-HG-HUD-REGRESSION-201',NULL,'regionwright,tests,regression,hunting,gathering');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-470','implementation','Scaffold Regionwright Hunting & Gathering mini-HUD','Resolved as a built v0.1.0 source/dist scaffold.','Keep it uncut-over while Hunting is designed; after Hunting has a stable API, integrate it into the HUD and then plan live module/control migration.','251/251 tests and source/dist hash agreement are complete; live cutover requires a separate approved migration checkpoint.','P0','closed','runtime','SRC-HG-HUD-BUILD-200'),
('O-471','implementation','Plan Hunting & Gathering live cutover','The new umbrella HUD exists but the live world still uses standalone Fishing/Mining ownership and controls.','Design Hunting first, then decide when the umbrella package should become live owner and remove legacy duplicate controls without changing subsystem flags/data.','Stable Hunting API plus migration plan and live-world verification.','P1','open','runtime','SRC-HG-HUD-BUILD-200');
-- Regionwright Hunting v0.1 design 2026-10-04.
INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('SRC-HUNTING-V01-202','Regionwright Hunting v0.1 gameplay design','conversation','project','Direct user design decisions','active','docs/REGIONWRIGHT-HUNTING-GATHERING-ROADMAP.md','2026-10-04','hunting v0.1 design','Visible Survival tracking, visible Stealth range, realistic bow physics, and visible Survival harvest. Dedicated flagged Hunting Bow only.');
INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-886','hunting-gathering',NULL,'Hunting v0.1 core loop','Hunting uses visible D&D5e Survival to determine quarry quality, visible Stealth to determine real shot distance and target scale, a mouse/draw/release bow minigame driven by draw strength + distance + gravity + wind + aim sway, and visible Survival to harvest after a lethal shot.','project','canonical','locked','SRC-HUNTING-V01-202',NULL,'regionwright,hunting,survival,stealth,ballistics,harvest'),
('F-887','hunting-gathering',NULL,'Hunting requires a dedicated Hunting Bow','Real Hunting accepts only the Regionwright Hunting Bow identified by the module huntingBow flag. Generic bows and name matching do not satisfy the equipment gate. Test mode is exempt.','project','canonical','locked','SRC-HUNTING-V01-202',NULL,'regionwright,hunting,bow,equipment');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-411','Hunting bow qualification','Require a dedicated module-owned Hunting Bow using an exact Regionwright flag, with no generic bow or name fallback.','There are too many bow variants to infer hunting compatibility safely, and a dedicated item keeps the minigame equipment contract clear.','project','locked','user','SRC-HUNTING-V01-202','Review only if explicit hunting equipment variants are added later.');
INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
