INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-888','hunting-gathering',NULL,'Hunting v0.2.0 prototype is built','Regionwright: Hunting & Gathering v0.2.0 contains visible Survival tracking, visible Stealth range selection, a mouse-aimed hold-to-draw/release shooting prototype with draw strength, real distance, gravity, crosswind, deterministic live sway/fatigue, deer hit zones, and visible Survival harvesting. Real hunts require the exact flagged Hunting Bow; test hunts bypass equipment and rewards.','project','safe_use','provisional','SRC-HUNTING-V01-BUILD-203',NULL,'regionwright,hunting,v0.2.0,ballistics,bow'),
