INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-892','regionwright-ui',NULL,'Regionwright uses a Foundry-like flat window language','Regionwright UI should use the Foundry application window as the primary visual surface, with translucent charcoal gray content, neutral text, subtle dividers, and no decorative nested card panels for routine sections. Borders are reserved for functional interactive elements such as game canvases, controls, tabs, and buttons.','project','canonical','locked','SRC-RW-UI-REFRESH-205',NULL,'regionwright,ui,foundry,charcoal,flat,panels');
