INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-920','hunting-gathering',NULL,'Hunting v0.3.6 uses a strongly back-loaded smooth draw curve','The draw target is approximately 50% at 0.46s, 75% at 1.47s, 90% at 2.74s, 95% at 3.32s, and 100% at 4.00s. The curve is continuous and smooth rather than piecewise stepped.','project','canonical','locked','SRC-HUNTING-DRAWCURVE-220','F-913','regionwright,hunting,draw,gradient,v0.3.6');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-420','Hunting draw gradient','Use a smooth back-loaded time curve so the first half is fast, the middle slows sharply, and the final quarter crawls to full draw.','The prior physically inspired work curve was still too fast through the middle and did not communicate the desired heavy-bow resistance in play.','project','locked','user','SRC-HUNTING-DRAWCURVE-220','Tune full draw time or curve constants only from live play.');
