INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-929','hunting-gathering',NULL,'Hunting v0.3.8 stamina playtest is live','The live v0.3.8 build adds a visible Stamina gauge. Drawing drains stamina as 1 + 16*strength^2 per second, full draw leaves about 56 stamina from fresh, full-draw holding then lasts about 3.2 seconds, and lowering recovers after a 0.6s delay at 24 stamina per second.','project','safe_use','provisional','SRC-HUNTING-STAMINA-BUILD-225',NULL,'regionwright,hunting,stamina,v0.3.8,playtest'),
('F-930','hunting-gathering',NULL,'Hunting v0.3.8 validation passed','The stamina revision passes 275/275 Regionwright tests, source/dist and installed hashes agree, and regionwright-testmap serves v0.3.8 as PID 19700.','project','safe_use','provisional','SRC-HUNTING-STAMINA-BUILD-225',NULL,'regionwright,hunting,tests,deploy,v0.3.8');
