INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-943','hunting-gathering',NULL,'Hunting v0.3.12 uses one synchronized flight clock','Arrow animation, quarry movement, and impact resolution use the same real RK4 flight duration. Visual flight is no longer capped at 1.1 seconds or used to fast-forward quarry motion.','project','canonical','locked','SRC-HUNTING-LEADSYNC-232',NULL,'regionwright,hunting,flight,sync,animation'),
('F-944','hunting-gathering',NULL,'Hunting v0.3.12 exposes movement-only dynamic lead','A subtle lead chevron predicts future quarry center at current arrow arrival time and updates with draw strength. It excludes wind and vertical drop and disappears for paused/negligibly moving quarry.','project','canonical','locked','SRC-HUNTING-LEADSYNC-232',NULL,'regionwright,hunting,lead,ui,movement'),
('F-945','hunting-gathering',NULL,'Hunting v0.3.12 uses actual-path tracer feedback','A short-lived tracer trail is rendered from sampled projectile trajectory after release so players can read and learn from the shot path.','project','canonical','locked','SRC-HUNTING-LEADSYNC-232',NULL,'regionwright,hunting,tracer,trajectory,feedback');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-426','Hunting moving-target aiming','Synchronize visual projectile motion to physics and provide a restrained movement-only dynamic lead reference plus tracer feedback.','Moving shots should be difficult because of real timing and compensation, not because the rendered arrow/deer timeline differs from hit-resolution physics.','project','locked','user','SRC-HUNTING-LEADSYNC-232','Tune lead-cue visibility only after live play.');
