INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-954','hunting-gathering',NULL,'Skyrim bow math is directly portable to Java','Public reverse-engineered Skyrim math uses ordinary scalar interpolation/multiplication and trigonometric velocity decomposition, so it translates directly to Java. Regionwright keeps its energy-derived launch and RK4 exterior ballistics because they are more physically grounded.','project','canonical','locked','SRC-HUNTING-STAMINAFEEL-238',NULL,'regionwright,hunting,skyrim,java,math'),
('F-955','hunting-gathering',NULL,'Hunting v0.3.15 uses a stronger heavy-bow stamina gradient','Stamina drain remains effort-weighted but uses 1 + 23*s^2 points/s, reaching 24/s at full draw. With the 2.5s quadratic draw timing, a fresh full draw leaves about 68.75 stamina and about 2.86s of full-draw hold.','project','canonical','locked','SRC-HUNTING-STAMINAFEEL-238','F-929','regionwright,hunting,stamina,heavy-bow,v0.3.15'),
('F-956','hunting-gathering',NULL,'Hunting v0.3.15 stamina and draw pulses communicate negative vs positive state','Below 50% stamina the meter pulses red with a continuously shortening period toward depletion, while draw milestone pulses/reached markers use success green. Reduced-motion preference disables pulse animation.','project','canonical','locked','SRC-HUNTING-STAMINAFEEL-238',NULL,'regionwright,hunting,ui,stamina,draw,pulse');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-429','Hunting heavy-bow exertion feedback','Use accelerating stamina depletion and red UI pulse rather than camera/reticle shake; use green draw milestone pulses.','This conveys increasing physical struggle without reintroducing motion that caused vertigo and aligns positive/negative feedback colors.','project','locked','user','SRC-HUNTING-STAMINAFEEL-238','Tune drain cap and pulse thresholds from live play only.');
