INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-959','hunting-gathering',NULL,'Future Hunting character scaling separates actor ability from bow physics','After neutral calibration, Dexterity will affect how quickly/effectively the character reaches draw states, while Constitution will affect stamina capacity, hold endurance, and recovery. Bow force-draw, stored energy, and projectile physics remain properties of the bow/system rather than the actor.','project','canonical','locked','SRC-HUNTING-ABILITYSCALING-240',NULL,'regionwright,hunting,dexterity,constitution,stamina,draw,future');
