INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-960','hunting-gathering',NULL,'Hunting v0.3.16 Ballistics Lab isolates vertical calibration','The GM-only lab uses stationary targets and zero wind to compare Current Hybrid, Meyer Reference, and Heavy Warbow Reference profiles at fixed ranges/draw strengths without movement, stamina, actor stats, or aim forgiveness confounds.','project','canonical','locked','SRC-HUNTING-BALLISTICSLAB-241',NULL,'regionwright,hunting,ballistics,lab,calibration'),
('F-961','hunting-gathering',NULL,'Hunting v0.3.16 separates raw fall from sighted error','The lab reports raw horizontal-launch fall independently from point-of-aim error after aiming/sight elevation and verifies the physical error against its screen-pixel projection.','project','canonical','locked','SRC-HUNTING-BALLISTICSLAB-241',NULL,'regionwright,hunting,drop,sight,projection'),
('F-962','hunting-gathering',NULL,'Hunting v0.3.16 uses one canonical projectile simulation result','Impact math, sampled trajectory data, and Ballistics Lab diagnostics derive from one projectile simulation result so visual and numerical projectile behavior cannot diverge by using separate formulas.','project','canonical','locked','SRC-HUNTING-BALLISTICSLAB-241',NULL,'regionwright,hunting,rk4,simulation,architecture');
INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-430','Hunting ballistics calibration','Diagnose live bow calibration with a deterministic lab and unified projectile simulation before changing gravity, drag, velocity, or aiming model.','Research shows current architecture is sound but current modern-reference constants and automatic pin sight may be inappropriate for the intended heavy self-bow feel.','project','locked','user','SRC-HUNTING-BALLISTICSLAB-241','After live lab testing choose final live profile/aiming model.');
